    'cli.doctor.php' => '{version} en {binary}',
    'cli.doctor.php_too_old' => '{version} en {binary} (candy-code requiere PHP 8.3+)',
    'cli.doctor.provider' => '{provider} (modelo {model})',
    'cli.doctor.provider_none' => 'ninguno seleccionado — el backend de eco sin conexión responderá (establezca CANDY_CODE_PROVIDER)',
    'cli.doctor.provider_shell' => 'backend de shell (tier $CANDY_CODE_BACKEND_CMD)',
    'cli.doctor.provider_unconstructable' => '{provider} está seleccionado pero no se puede construir: {error}',
    'cli.doctor.provider_unknown' => '{provider} está seleccionado pero no es un proveedor conocido — vea `candy-code models`',
    'cli.doctor.sandbox_binary' => '{backend} en {path}',
    'cli.doctor.sandbox_binary_absent' => '{backend} no encontrado en PATH',
    'cli.doctor.sandbox_nonlinux' => 'bashSandbox "{mode}" está configurado pero bubblewrap es solo para Linux y este host es {os}',
    'cli.doctor.sandbox_nonlinux_off' => 'bashSandbox está desactivado; bubblewrap es solo para Linux y este host es {os}',
    'cli.doctor.sandbox_off' => 'bashSandbox está desactivado; {bwrap}, y la jail se iniciaría aquí si estuviera habilitada',
    'cli.doctor.sandbox_off_blocked' => 'bashSandbox está desactivado; {bwrap}, y la jail no se iniciaría aquí aunque estuviera habilitada ({reason})',
    'cli.doctor.sandbox_ready' => 'bashSandbox "{mode}"; {bwrap}, y la jail se inicia',
    'cli.doctor.sandbox_refused' => 'bashSandbox "{mode}" está configurado pero la jail no se inicia ({reason}) — {remedy}',
    'cli.doctor.sandbox_remedy_apparmor' => 'instale bubblewrap, o añada un perfil en /etc/apparmor.d que conceda a bwrap espacios de nombres de usuario sin privilegios (el sysctl apparmor_restrict_unprivileged_userns es el recurso tosco)',
    'cli.doctor.sandbox_remedy_generic' => 'instale bubblewrap, o establezca bashSandbox en "off"',
    'cli.doctor.sandbox_remedy_seatbelt' => 'verifique que /usr/bin/sandbox-exec sigue funcionando en esta instalación de macOS, o establezca bashSandbox en "off"',
    'cli.doctor.server_ready' => 'pcntl, posix y ffi disponibles — `serve` puede iniciarse',
    'cli.doctor.server_refuses' => '`serve` se negará a iniciarse: {problems}',
    'cli.doctor.sessions' => '{count} sesión(es) almacenadas',
    'cli.doctor.settings_clean' => 'cada archivo de configuración contiene solo claves que candy-code lee',
    'cli.doctor.unknown' => 'desconocido',
    'cli.headless.permission_hint' => '  pista: una ejecución `-p` sin modo nombrado arranca en el modo `default` de consulta; las consultas desatendidas no tienen a nadie que responda, así que fallan en modo cerrado. Las ejecuciones con script pueden especificar --permission-mode bypass-permissions (o accept-edits) para continuar.',
    'cli.help.screen' => <<<'TXT'
CandyCode — Asistente de programación con IA para la terminal.

Uso:
  candy-code                       Iniciar la TUI interactiva (predeterminado)
  candy-code <dir>                 Iniciar la TUI con raíz en <dir>, que debe
                                   existir (solo como primer argumento)
  candy-code [<dir>] <words…>      Iniciar la TUI y enviar las palabras como su
                                   primer prompt, p. ej. candy-code fix the bug
  candy-code -c                    Continuar la sesión más reciente
  candy-code --resume [<id>]       Reanudar una sesión almacenada (selector si no hay id)
  candy-code -p <prompt>           Ejecutar un único prompt y salir (una sola vez)
  candy-code run "<prompt>"        Alias de -p "<prompt>" (modo de una sola vez)
  candy-code --output-format json  Salida JSON legible por máquina (una sola vez)
  candy-code --worktree [<name>]   Ejecutar esta sesión en un git worktree
                                   propio (se crea si no existe)

Subcomandos (ninguno abre la TUI ni necesita un proveedor, una clave de API ni una
terminal; cada uno responde y sale excepto serve y mcp serve, que se ejecutan hasta
detenerse — y attach, que es la excepción a ambos: ejecuta la TUI en una sesión de un servidor en ejecución
; acp ejecuta turnos para un editor, hasta que el editor se desconecta):
  bundles list           Listar los bundles de plugins que este directorio ve: nombre,
                         versión, tier y las superficies que cada uno incluye —
                         incluidos los hooks y .mcp.json que candy-code
                         se niega a ejecutar.
  bundles install <src>  Copiar un directorio de bundle, o clonar una URL git con un
                         clon de profundidad uno acotado, en la raíz de bundles del usuario
                         (~/.candy-code/bundles), donde solo usted es propietario.
  doctor                 Comprobar esta instalación e informar de cada problema que
                         encuentre: versión de PHP, las extensiones que el almacén de sesiones
                         y serve necesitan, el archivo de configuración, la política de
                         permisos, el proveedor seleccionado, la base de datos de sesiones
                         y la configuración MCP del proyecto. Sale con 1 si alguna
                         comprobación FALLA.
                         Distinto de la herramienta "doctor" invocable por el modelo, que
                         informa al modelo del protocolo de imágenes de la terminal.
  import claude          Vista previa de la importación de ajustes de Claude Code: lee el archivo de usuario de
                         Claude, además del archivo de ajustes .claude bajo la raíz de
                         lanzamiento cuando se indica --project, traduce sus listas de
                         permisos allow/deny/ask a permissionRules (la parte más estricta
                         siempre gana — deny vence a allow), mapea el modelo y nombra cada
                         clave sin destino como omitida. No se escribe nada hasta
                         confirmar: --yes acepta la vista previa impresa sin más, y
                         sin ella se pregunta en un terminal interactivo. La vista previa nombra
                         cada regla allow que ampliaría lo que se ejecuta sin preguntar.
  login <provider>       Inicia sesión en un proveedor: claude-code y codex ceden el
                         terminal a su propia CLI (el token nunca pasa
                         por candy-code); openai, anthropic y gemini
                         pegan una clave en el bloque providers del archivo de configuración;
                         los demás nombran a quien realmente posee su credencial.
  models                 Lista los proveedores que esta instalación puede seleccionar y el
                         modelo predeterminado de cada uno; "*" marca el
                         seleccionado.
  session list [--all|--archived|--children] [--limit N]
                         Lista las sesiones almacenadas, primero las fijadas y luego las más
                         recientes: id, última actualización, tipo, turnos, proveedor/modelo
                         y nombre (★ marca una fila fijada). --children añade
                         filas de sub-agentes y en segundo plano, --archived añade
                         las archivadas, --all añade ambas; 20 filas salvo que
                         --limit indique otra cosa.
  session show <target>  Imprime los detalles y la transcripción de una sesión.
  session import <path> [--format auto|…] [--name <title>] [--force]
                         Importa un archivo de transcripción como sesión
                         nueva: una exportación de candy-code o el historial
                         de claude-code, codex u opencode (--format auto deduce).
  session rename <target> <title…>
                         Renombra una sesión; las palabras tras el destino son
                         el título.
  session delete <target> [--with-children]
                         Elimina una sesión. Los hijos sub-agente se van con ella;
                         las ramas se conservan salvo --with-children.
  session pin|unpin|archive|unarchive <target>
                         Fija una sesión (se lista primero, nunca se purga), o
                         la archiva (oculta de la lista predeterminada, conservada).
                         <target> es un id, un nombre o un prefijo de id único.
                         Sale con 1 si nada coincide, con 2 si un prefijo es
                         ambiguo (se listan los candidatos).
  mcp list               Lista los servidores MCP que declara .mcp.json, SIN
                         iniciar ninguno. Informa en su lugar cuando el archivo
                         no existe, se resuelve fuera del árbol del proyecto, o está
                         presente pero la raíz del proyecto no es de confianza.
  mcp auth login <server> [token-url] [authorize-url] [registration-url]
                         Autentica un servidor MCP declarado con OAuth:
                         abre (o imprime) su URL de autorización, captura la
                         redirección loopback y guarda los tokens para luego.
  mcp trust              Aprueba el .mcp.json de este proyecto tal como está: añade
                         la raíz a "trustedProjectMcp" y registra el comando, los
                         argumentos y el entorno de cada servidor, de modo que un cambio
                         posterior en cualquiera de ellos se rechaza al lanzar hasta
                         re-aprobar. No inicia nada.
  mcp import claude|opencode|claude-project <path> [--write user]
                         Traduce una configuración MCP ajena e imprime el bloque
                         .mcp.json equivalente en stdout. Solo imprime
                         por defecto; --write user añade las entradas
                         traducidas al ~/.candy-code/mcp.json del usuario
                         (una colisión de nombre rechaza toda la escritura, y la
                         capa de proyecto nunca se escribe). Los renombramientos que
                         hizo la traducción se listan en stderr.
  mcp serve [--root PATH]
                         Sirve candy-code como servidor MCP por stdio:
                         un marco JSON-RPC por línea de entrada, una respuesta por línea
                         de salida, hasta que stdin se cierra. Las llamadas a herramientas
                         ejecutan el catálogo de solo lectura (Read, Glob, Grep, Ls, RepoMap),
                         confinado a la raíz del workspace, a través del PermissionGate
                         del lanzamiento y la cadena de hooks PreToolUse — este es el
                         servidor MCP que un cliente puede lanzar; el WebSocket
                         `candy-code serve` aún no habla MCP. Se ejecuta hasta
                         detenerlo.
  lsp install <language> Instala el servidor de lenguaje fijado para un
                         lenguaje: el paquete npm o el binario de release verificado
                         por checksum, en la raíz de instalación privada bajo
                         tu home. `lsp list` responde qué lenguajes son
                         instalables.
  lsp list               Informa de cada lenguaje instalable: su versión
                         fijada, dónde está instalado su servidor (o que no lo
                         está), y si existe una release para el SO y la
                         arquitectura de esta máquina. No inicia nada,
                         no descarga nada.
  self-update [--check] [--rollback] [--allow-unsigned] [--channel=stable|dev]
                         Reemplaza esta instalación phar con la última release
                         publicada de candy-code, verificada por sha256 contra el
                         sidecar de la release ANTES del intercambio; el phar en
                         ejecución se conserva como <phar>.old y --rollback restaura
                         exactamente esa copia una vez. Cuando una clave pública de
                         firma está fijada en la fuente de la release, la firma
                         candy-code.phar.minisig debe verificarse también (--allow-unsigned omite
                         solo esa parte). --check solo informa la versión actual vs
                         la última y sale con 1 cuando hay una actualización. Una
                         instalación de Composer se rechaza en voz alta, nombrando el
                         comando composer update a ejecutar en su lugar. Una
                         instalación de desarrollo sigue la release rolling candy-code/dev
                         por defecto (está al día cuando el commit objetivo de la release
                         coincide con el sha del stamp) y --channel
                         selecciona explícitamente una u otra rama.
  serve [--host <ip>] [--port <n>] [--allow-remote] [--allowed-host <list>]
        [--allowed-ips <list>] [--allowed-origin <list>] [--allow-dir-browse]
        [--browse-root <dir>] [--web-root <dir>] [--no-web] [--allow-bypass]
        [--allow-root] [--detach] [--parent-pid <pid>]
        [--tls-cert <file>] [--tls-key <file>]
                         Ejecuta el servidor WebSocket + HTTP al que se conecta la
                         interfaz web, en primer plano hasta Ctrl+C. Escucha en
                         127.0.0.1:7420 de forma predeterminada e imprime una URL
                         de inicio de sesión cuyo código de un solo uso se intercambia
                         por una cookie del navegador; todo cliente lo necesita, o el
                         token en ~/.candy-code/server/token, loopback incluido. Opciones:
      --host <ip>        Dirección de escucha (predeterminada 127.0.0.1; localhost y ::1
                         también cuentan como loopback). Cualquier otra dirección se
                         rechaza salvo que se indique también --allow-remote.
      --port <n>         Puerto de escucha (predeterminado 7420; 0 elige uno libre).
      --allow-remote     Permite un --host no loopback. Sin --tls-cert y
                         --tls-key es HTTP sin cifrar: pon un proxy inverso TLS
                         delante, o sirve TLS directamente (ver abajo). En
                         0.0.0.0 o :: el servidor responde a las direcciones propias
                         de esta máquina, y la URL de inicio de sesión las nombra.
      --tls-cert <file>  Certificado PEM con el que el listener sirve TLS,
                         dado junto con --tls-key. La URL de inicio de sesión
                         pasa a https://, la cookie de sesión lleva Secure,
                         y un cliente http:// en texto plano no recibe respuesta.
      --tls-key <file>   Clave privada PEM para --tls-cert: un archivo legible
                         sin bits de grupo ni de otros, que coincida con el
                         certificado. Un par inválido o incompleto se rechaza al iniciar.
      --allowed-host <list>
                         Nombres de host (o host:puerto) extra separados por
                         comas a los que el servidor responde, p. ej. un nombre DNS
                         de esta máquina. Repetible.
      --allowed-ips <list>
                         IPs de cliente o rangos CIDR separados por comas (p. ej.
                         1.2.3.4,10.0.0.0/8) autorizados a conectar; cualquier otra
                         dirección recibe 403 antes del inicio de sesión. Loopback
                         siempre está permitido. Sin definir: sin filtro de dirección.
                         Repetible.
      --allowed-origin <list>
                         Orígenes de navegador extra separados por comas
                         (http(s)://host[:puerto]) permitidos junto al propio
                         del servidor. Repetible.
      --allow-dir-browse Permite a los clientes autenticados elegir el directorio
                         donde inicia una sesión nueva: pueden listar nombres de
                         directorio (nunca archivos) bajo --browse-root. Desactivado por defecto.
      --browse-root <dir>
                         Directorio al que --allow-dir-browse está limitado
                         (predeterminado: tu directorio personal).
      --web-root <dir>   Sirve la interfaz web desde <dir> en lugar del paquete
                         sugarcraft/candy-code-web instalado.
      --no-web           Sirve solo la API y WebSocket, sin archivos de interfaz.
      --allow-bypass     Permite que las sesiones se ejecuten en bypass-permissions o dont-ask
                         (rechazado por defecto; las sesiones del servidor inician en
                         default salvo que --permission-mode indique lo contrario).
      --allow-root       Permite ejecutarse como root (rechazado por defecto).
      --detach           Ejecuta en segundo plano: imprime la URL y el pid una vez
                         enlazado el puerto, y sale; el servidor registra en
                         server.log en su directorio de estado.
      --parent-pid <pid> Detiene el servidor cuando el proceso <pid> termina (para un
                         editor o TUI que inicia un servidor privado).
                         Rechaza iniciar sin ext-pcntl, ext-posix y
                         ext-ffi (ver doctor). Sale con 1 si el puerto está ocupado o
                         ya hay un servidor corriendo desde el mismo directorio de estado.
  serve status           Informa del servidor en ejecución: pid, URL, root, tiempo activo y
                         si GET /api/health responde. Sale con 1 cuando no
                         hay ninguno.
  serve stop [--force]   Detenerlo: SIGTERM, hasta 30 s para drenar, luego SIGKILL.
      --force            SIGKILL de inmediato.
  serve logs [-f]        Muestra el final del registro de un servidor en segundo plano.
  -f, --follow           Sigue mostrando lo que se añade hasta que se detenga.
  serve url [--qr]       Muestra una URL de inicio de sesión con un código de un solo uso nuevo.
      --qr              Muestra cada URL de inicio de sesión como un código QR escaneable en terminal.
  serve token [--rotate] Muestra el token de propietario que envían los clientes bearer.
      --rotate           Reemplázalo; un servidor en ejecución conserva el anterior hasta
                         que se reinicie.
  attach [<session>] [--url <url>]
                         Ejecuta la TUI en una sesión de un candy-code
                         serve en ejecución: el servidor ejecuta cada turno y sus
                         herramientas, y esta terminal los muestra y responde a las
                         preguntas de permiso que plantean. <session> es un id, un
                         nombre o un prefijo de id único de una de las sesiones del
                         servidor; sin él se crea una nueva. El servidor es el
                         que serve status informa, con su token tomado de
                         CANDY_CODE_SERVER_TOKEN o del archivo de token del
                         directorio de estado. Salir desconecta; un turno en
                         ejecución continúa. Sale con 1 si ningún servidor responde.
      --url <url>        Conectar al servidor en <url> (la dirección que
                         serve imprime) en su lugar.
  acp                    Ejecuta como agente del Protocolo de Cliente de Agente: el
                         editor (Zed, JetBrains, Neovim) lo inicia y habla
                         JSON-RPC por su stdin y stdout. Las sesiones se abren en
                         la raíz del proyecto del editor, los turnos se ejecutan aquí con este
                         proveedor y herramientas de la instalación, y el editor responde
                         sus preguntas de permisos. No para un terminal: stdout
                         solo transporta el protocolo (todo lo demás va a
                         stderr). Sale con 0 cuando el editor cierra stdin.
  completion bash|zsh|fish
                         Escribe un script de autocompletado de shell a stdout, p. ej.
                         eval "$(candy-code completion bash)".
  usage [7|30|all] [--session <target>]
                         Resume el libro de gastos persistente por día y modelo:
                         la misma página que `/usage` imprime, sobre el mismo
                         pliegue compartido. 7 y 30 toman días UTC completos,
                         hoy incluido; all (o sin operando) abarca todo el libro,
                         y una ventana fuera de ese conjunto se rechaza en vez
                         de ampliarse en silencio. --session reduce a una sesión
                         por id, nombre o prefijo único; --output-format json
                         emite el mapa de hechos del que se construyó la página. Un
                         libro ilegible indica su motivo y sale con 1;
                         los dólares de pliegues que incluyen un modelo sin precio
                         se imprimen como un límite inferior ≥, nunca como suma simple.

Opciones:
  -p, --prompt <text>    Proporciona un prompt en la línea de comandos (modo one-shot)
      --output-format <format>
                         Formato de salida: "text" (predeterminado), "json" o
                         "stream-json" (eventos NDJSON, respuesta al final)
      --root <dir>       Usa <dir> como raíz del proyecto en vez del directorio
                         actual. También acepta --root=<dir> (la forma a usar
                         cuando <dir> empieza con "-"); no puede omitirse.
                         Nombrar una raíz aquí Y como argumento posicional se
                         rechaza en vez de que una gane en silencio.
      --config <file>    Lee ajustes, permisos y raíces de hooks de confianza de
                         <file> en vez de ~/.candy-code/config.json. También
                         acepta --config=<file>. Debe existir ya, ser
                         legible, ser de tu propiedad, y ni él ni su
                         directorio pueden ser escribibles por todos — transporta la
                         política de permisos, así que se le exige el mismo estándar
                         que ~/.candy-code/config.json (un archivo bajo /etc o
                         /tmp se rechaza normalmente por una de esas razones).
                         Solo se mueve el ARCHIVO: agentes, skills, workflows,
                         sesiones y memoria permanecen en ~/.candy-code.
      --model <name>     Usa <name> como modelo de conversación, anulando
                         $CANDY_CODE_MODEL y el predeterminado del proveedor. También
                         acepta --model=<name>. Selecciona un modelo, no un proveedor
                         — el proveedor sigue viniendo de $CANDY_CODE_PROVIDER o
                         el ajuste `provider` persistido, y ambos son
                         ejes independientes.
      --permission-mode <mode>
                         Ejecuta bajo <mode> en vez del modo del archivo de
                         config. También acepta --permission-mode=<mode>. Máxima
                         precedencia: supera a $CANDY_CODE_PERMISSION_MODE y
                         la clave permissionMode del config. Uno de: default,
                         accept-edits, plan, auto, dont-ask,
                         bypass-permissions. Sin ninguno, la TUI y -p
                         arrancan en default (pregunta antes de escrituras y comandos
                         de shell); solo un daemon lanzado localmente arranca en
                         bypass-permissions.
      --max-cost <usd>   Limita esta ejecución a <usd> dólares US de gasto
                         reportado: el turno que cruzaría el techo se
                         rechaza y no se envía. También acepta --max-cost=<usd>.
                         Máxima precedencia: supera a $CANDY_CODE_MAX_COST y
                         la clave maxCostUsd del config. Fracciones permitidas, un
                         $ inicial aceptado ($2.50); cero y negativos se
                         rechazan en vez de leerse como "sin límite". /budget aún
                         sube o limpia el límite de la sesión en ejecución.
      --max-turns <n>    Limita esta ejecución a <n> pasos del bucle de herramientas: el
                         turno que los agota se detiene donde está y lo indica.
                         También acepta --max-turns=<n>. Máxima precedencia:
                         supera la clave maxToolSteps del ajuste (este eje
                         no tiene variable de entorno). Un número entero
                         positivo; cero se rechaza en vez de leerse como "sin
                         límite", y un valor inutilizable rechaza la ejecución
                         en vez de ceder en silencio al ajuste.
      --json-schema <path-or-json>
                         Restringe la respuesta a un JSON Schema: un documento
                         {"type":"object",...} en línea o una ruta a un archivo
                         que lo contenga. También acepta --json-schema=<value>;
                         la forma = es la que usar cuando la ruta empieza
                         con "-". Solo proveedores que reportan soportar
                         respuestas restringidas por schema ejecutan la petición
                         — cualquier otro la rechaza con exit 2 en vez de
                         facturar una respuesta sin restricción. El schema
                         controla la petición de auto-cierre del turno; los pasos
                         que continúan un bucle de herramientas quedan libres (una
                         respuesta JSON forzada no puede llevar llamadas a herramientas).
      --append-system-prompt <text-or-@file>
                         Añade reglas de operador al prompt de sistema de esta
                         única ejecución: texto en línea, o @ruta a un archivo que
                         las contenga. También acepta --append-system-prompt=<value>;
                         la forma = es la que usar cuando la ruta empieza
                         con "-". Las reglas llegan como un bloque
                         de instrucciones personales más, nunca una anulación:
                         no pueden reemplazar ni degradar las capas superiores, y
                         los marcadores de bloque falsificados en el texto se neutralizan.
                         Limitado al mismo tamaño que un documento de instrucciones.
                         Solo con -p o el verbo run: un lanzamiento sin
                         prompt al que añadir rechaza con exit 2 en lugar de
                         ignorar silenciosamente las reglas que diste.
  -c, --continue         Reabre la sesión usada más recientemente, transcripción
                         y todo, en lugar de iniciar una nueva. Sin esta opción
                         cada lanzamiento abre una sesión nueva; Up en un
                         cuadro de entrada vacío aún recupera prompts de sesiones anteriores.
      --resume [<id|name>]
                         Reabre una sesión guardada por id, prefijo de id único o
                         nombre (véase `session list`). Sin valor, abre el
                         selector de sesión al iniciar; junto a -p un destino ES
                         obligatorio (la transcripción alimenta el one-shot y la
                         respuesta se guarda de vuelta en la fila). También acepta
                         --resume=<id>. No combinable con --continue.
      --worktree [<name>]
                         Ejecuta toda la sesión dentro de un git worktree
                         main-<name> en la rama candy-code/<name>, creado
                         en el primer uso; sin nombre, el worktree recibe uno
                         elegido automáticamente. Al salir, un worktree sin
                         commits ni ediciones se elimina; uno con
                         trabajo se conserva y anuncia su ruta. Rechazado
                         fuera de un git work tree y junto a `serve`.
      --incognito        Inicio que no guarda nada: sin fila de sesión, sin
                         transcripción, sin escrituras automáticas de memoria al final del turno.
                         Lo que la ejecución produjo vive solo en el proceso;
                         sesiones y notas guardadas ANTES siguen siendo legibles.
                         Rechazado junto a --continue o --resume, que reabren
                         sesiones guardadas.
      --restricted       Inicio que no puede ejecutar código: Bash, PtyRun, Task,
                         Workflow, ShellStop y mcp_call se eliminan de
                         cada conjunto orientado al modelo durante toda la sesión, y
                         /permissions no puede devolverlos. Las herramientas de archivo siguen,
                         bajo la restricción de rutas existente. También acepta
                         --restricted=true|false, para que un wrapper pueda anular
                         un alias que lleve la bandera sola. Sobrevive al reinicio.
      --safe-mode        Inicio que ignora toda confianza: cada raíz
                         de proyecto confiable responde como no confiable (hooks, MCP
                         de proyecto y shells de comandos), no se cargan bundles, y no
                         se descubren skills, comandos ni agentes externos.
                         La configuración, skills y comandos nativos se conservan. También
                         acepta --safe-mode=true|false para anular un
                         alias. Sobrevive al reinicio.
  -h, --help             Muestra este mensaje de ayuda
  -v, --version          Muestra la versión instalada y sale
      --                 Fin de opciones: todo argumento posterior es posicional,
                         nunca una bandera

Variables de entorno:
   CANDY_CODE_PROVIDER    Proveedor a usar: openai, azure, anthropic, claude-code,
                          codex, sglang, bedrock, vertex, gemini,
                          openrouter, custom
   CANDY_CODE_MODEL       Nombre del modelo (anula el predeterminado del proveedor; --model gana)
   CANDY_CODE_PERMISSION_MODE
                          Modo de permisos inicial, anulando la clave
                          permissionMode de configuración (--permission-mode gana)
   CANDY_CODE_BACKEND_CMD Comando de shell para un adaptador de backend personalizado, bajo el
                          contrato PROSE: recibe historial JSON por stdin, escribe
                          el texto de respuesta en stdout, que se usa literalmente
                          (recortado solo en los extremos, así que cada salto de línea, línea
                          en blanco e indentación internos se conservan).
   CANDY_CODE_BACKEND_CMD_STREAM
                          El mismo shell-out bajo el otro contrato, un FLUJO DE
                          TOKENES: un token por línea, el salto de línea entre dos
                          tokens es enmarcado y se descarta, y una línea en BLANCO es
                          un salto de línea literal en la respuesta. El callback se dispara por
                          token conforme el comando los produce, pero el bucle de lectura
                          es síncrono, así que la pantalla se repinta una vez al final
                          en lugar de token por token. No intercambiable con
                          CANDY_CODE_BACKEND_CMD en ninguna dirección — un wrapper
                          de prosa ejecutado con esta variable vuelve sin ningún
                          salto de línea y cada línea en blanco colapsada a una.
                          CANDY_CODE_BACKEND_CMD tiene prioridad cuando ambos están definidos.
                          Para ambos, no definido, vacío y solo espacios en blanco cuentan
                          como ausentes.
   CANDY_CODE_DISABLE_PARALLEL_TOOL_CALLS
                          Ejecuta las llamadas a herramientas de un turno estrictamente una a una.
                          El despacho concurrente es el predeterminado y solo
                          agrupa herramientas no mutantes; esta es la válvula de escape.
                          Persistirlo como "parallelToolCalls": false en
                          ~/.candy-code/config.json.
   CANDY_CODE_PARALLEL_TOOL_DEADLINE
                          Segundos que un grupo concurrente puede ejecutarse antes de que sus
                          rezagados sean eliminados y reportados como llamadas fallidas
                          (predeterminado 90, debe ser 1-119; una fracción se trunca).
                          Persistirlo como "parallelToolDeadlineSeconds".
                          Precedencia: esta variable, luego la clave persistida,
                          entonces el valor predeterminado. Un valor fuera de 1-119, o uno que
                          no es un número en absoluto, no cuenta como establecido —
                          pasa a la siguiente fuente en lugar de
                          descartarla.
   CANDY_CODE_ADVISOR_MODEL
                          El modelo que la herramienta `Advisor` consulta para una segunda
                          opinión: una completación sin herramientas, facturada como
                          cualquier otra llamada. A diferencia de CANDY_CODE_TITLE_MODEL,
                          no hay alternativa barata — no establecido significa que la
                          herramienta no se ofrece en absoluto. Se lee al iniciar.
   CANDY_CODE_TITLE_MODEL El modelo barato usado para nombrar automáticamente una sesión tras
                          su primer intercambio; predeterminado al del proveedor.
   CANDY_CODE_SUMMARY_MODEL
                          El modelo que escribe resúmenes de compactación;
                          predeterminado al de la propia conversación, que reutiliza
                          la caché de prompts.
   CANDY_CODE_CONTEXT_PRUNING
                          auto, manual u off: cómo una sesión poda su
                          contexto cuando /pruning no ha elegido (predeterminado auto).
   CANDY_CODE_MAX_COST    Un techo de gasto para esta sesión, en dólares estadounidenses
                          (decimales permitidos; se acepta un "$" inicial;
                          --max-cost tiene prioridad). Un turno que supera el techo
                          es rechazado.
   CANDY_CODE_CONNECT_TIMEOUT
                          Límite de la fase de conexión, en segundos (decimales
                          permitidos; predeterminado 15.0), para los
                          transportes HTTP del proveedor. Limita solo el establecimiento
                          de la conexión — no es un tiempo de espera total de la petición. El tiempo
                          que un servidor de streaming conectado puede tardar en enviar sus
                          cabeceras de respuesta es el ajuste
                          streamHeaderTimeoutSeconds, independiente.
   CANDY_CODE_SEARCH_ENDPOINT
                          API de búsqueda que consulta la herramienta WebSearch integrada.
   CANDY_CODE_SESSION_RETENTION_DAYS
                          Un número entero positivo de días: cada inicio elimina
                          sesiones sin uso durante al menos ese tiempo.
   CANDY_CODE_SHARE_UPLOAD_URL
                          Host de subida retirado: /share nunca sube
                          a ningún sitio. Si está establecido, la exportación local se guarda
                          igualmente y la respuesta rechaza la clave con claridad y menciona
                          /share serve, que publica una página de snapshot
                          autoalojada en tu propio candy-code serve.
   CANDY_CODE_WORKTREES_DIR
                          Directorio base bajo el cual se crean worktrees de git
                          por compañero de equipo.
   CANDY_CODE_DISABLE_MOUSE
                          Cualquier valor distinto de vacío o 0 desactiva el seguimiento
                          del ratón por completo.
   CANDY_CODE_DISABLE_MOUSE_CLICKS
                          Cualquier valor distinto de vacío o 0 ignora los gestos de clic
                          manteniendo el desplazamiento con la rueda.
   CANDY_CODE_DISABLE_PROMPT_CACHE
                          Cualquier valor distinto de vacío o 0 desactiva los puntos de
                          corte de caché de prompts del proveedor.
   CANDY_CODE_DISABLE_PROMPT_SUGGESTIONS
                          Cualquier valor distinto de vacío o 0 desactiva la sugerencia
                          de siguiente mensaje en gris (→ la acepta) tras cada turno.
   CANDY_CODE_DISABLE_AUTO_MEMORY
                          Cualquier valor distinto de vacío o 0 desactiva el autoguardado
                          de hechos duraderos como notas tras un turno, y
                          la pasada de sueño que integra el diario de compactación
                          en ellas.
   CANDY_CODE_DISABLE_MODEL_METADATA
                          Cualquier valor distinto de vacío o 0 desactiva la lectura y
                          actualización de la base de datos de modelos LiteLLM que dimensiona y
                          precia modelos sin cifra integrada.
   CANDY_CODE_NO_UPDATE_CHECK
                          Cualquier valor distinto de vacío o 0 desactiva la comprobación diaria
                          de versiones phar y el aviso de actualización al inicio que genera;
                          no sale ninguna petición del proceso y un aviso
                          obsoleto en caché ya no se muestra.
   CANDY_CODE_DISABLE_SYMBOL_MAP
                          Cualquier valor distinto de vacío o 0 excluye el mapa de símbolos
                          clasificado del prompt de sistema.
   CANDY_CODE_BACKGROUND  light o dark — fuerza lo que el tema adaptativo
                          cree sobre el fondo del terminal, omitiendo
                          la sonda OSC 11 y COLORFGBG.
   CANDY_CODE_DEBUG_SKILLS
                          Cualquier valor distinto de vacío o 0 devuelve las líneas de
                          omisión y directorio rechazado de SkillLoader a
                          stderr.
   CANDY_CODE_DEBUG_COMMANDS
                          Cualquier valor distinto de vacío o 0 devuelve las líneas de
                          rechazo de descubrimiento de CommandLoader a stderr.
   CANDY_CODE_DEBUG_RULES Cualquier valor distinto de vacío o 0 devuelve las líneas de
                          rechazo de descubrimiento de RuleLoader a stderr.
   CANDY_CODE_DEBUG_STREAM
                          Cualquier valor distinto de vacío o 0 mantiene la línea de Chat
                          "onToken observer threw" en stderr. El
                          desprendimiento en sí ocurre de todos modos.
   CANDY_CODE_SERVER_HOST La dirección a la que `serve` se vincula (--host tiene prioridad).
   CANDY_CODE_SERVER_PORT El puerto al que `serve` se vincula (--port tiene prioridad).
   CANDY_CODE_SERVER_ALLOWED_ORIGINS
                          Orígenes extra separados por comas que `serve` acepta
                          (--allowed-origin tiene prioridad).
   CANDY_CODE_SERVER_ALLOWED_HOSTS
                          Nombres de host extra separados por comas a los que `serve` responde
                          (--allowed-host tiene prioridad).
   CANDY_CODE_SERVER_ALLOWED_IPS
                          IPs de cliente o CIDRs separados por comas que `serve` admite
                          además de loopback (--allowed-ips tiene prioridad).
   CANDY_CODE_SERVER_WEB_ROOT
                          Directorio desde el que `serve` sirve la interfaz web (--web-root
                          tiene prioridad).
   CANDY_CODE_SERVER_TOKEN
                          El token que `serve` requiere, en lugar del que está en
                          su directorio de estado (mínimo 32 caracteres; para
                          contenedores).
   CANDY_CODE_SERVER_DIR  El directorio donde `serve` guarda su token, lock,
                          registro de descubrimiento y log (predeterminado:
                          ~/.candy-code/server; creado con 0700).
   CANDY_CODE_SERVER_PARENT_PID
                          Un proceso con el que `serve` se detiene (--parent-pid tiene prioridad).
   CANDY_CODE_MCP_DISABLE
                          1, true o yes (sin distinguir mayúsculas) silencia el MCP
                          del proyecto por completo: .mcp.json se trata como inexistente, no
                          se inicia ningún servidor. Sin definir, 0 o cualquier otro valor mantiene
                          MCP habilitado — a diferencia de las variables de tipo flag,
                          solo estas tres palabras son válidas.
   CANDY_CODE_QUIET_LOGS  1, true o yes (sin distinguir mayúsculas) silencia el
                          canal lateral de error_log() en todo el proceso en su único
                          destino; sin definir, 0 o cualquier otro valor mantiene
                          los diagnósticos fluyendo. Solo en el arranque, sin clave de ajustes.
   CANDY_CODE_REDUCED_MOTION
                          1, true o yes (sin distinguir mayúsculas) fija el spinner
                          del agente en un único fotograma estático — para usuarios
                          sensibles al movimiento o con movimiento reducido. Se lee una vez al iniciar;
                          no existe clave de ajustes.
   CANDY_CODE_SD_BASE_URL URL base del servidor Stable Diffusion de estilo
                          A1111 (sdapi) al que se conecta el transporte de medios.
                          Precedencia: una anulación explícita en código, luego esta
                          variable, luego el ajuste sd.baseUrl.
   CANDY_CODE_MEDIA_RENDER_MODE
                          Cómo se pintan las imágenes generadas en la terminal
                          (la capa de entorno del ajuste ui.imageRenderMode; ver
                          docs/ENVIRONMENT.md para las palabras aceptadas).
   CANDY_CODE_ALLOW_ROOT_TESTS
                          Establecer exactamente en 1 para permitir que la SUITE DE PRUEBAS
                          de candy-code se ejecute como root; sin definir o cualquier otro valor, la suite
                          se niega a iniciarse con euid 0. Nada del arranque de
                          candy-code cambia — la suite no es una
                          superficie orientada al usuario.
   CANDY_CODE_TOOL_INPUT  El mapa completo de argumentos de la llamada actual a una
                          herramienta de script de usuario, codificado en JSON, exportado al proceso
                          hijo de cada ejecución de una herramienta en ~/.candy-code/tools
                          ; la app lo escribe, nunca lo vuelve a leer, y
                          nadie lo define por sí mismo.
   CANDY_CODE_OTEL_BATCH_SIZE
                          Cuántos spans transporta un lote de exportación OTLP
                          (predeterminado 64, limitado a 1..2048).
   CANDY_CODE_OTEL_TIMEOUT
                          Segundos que puede durar cada intento de exportación OTLP
                          (predeterminado 3; un valor no positivo o mal formado
                          recurre al predeterminado).

   docs/ENVIRONMENT.md tabula cada variable que esta compilación lee, con su
   contrato completo.

Códigos de salida (modo one-shot y cada subcomando):
  0                      El prompt se ejecutó y produjo una respuesta, o el
                         subcomando respondió
  1                      Se ejecutó y falló: el backend lanzó (host inaccesible,
                         clave rechazada, error de modelo) — un reintento puede ayudar — o un
                         subcomando se ejecutó y falló (una comprobación de doctor devolvió
                         FAIL, un verbo `session` no encontró tal sesión, un
                         .mcp.json confiable no pudo ser analizado)
  2                      Error de uso o configuración, no se intentó nada
                         y un reintento no ayudará: sin prompt, una
                         flag no reconocida, un argumento suelto que no nombra
                         ningún directorio existente (un prompt necesita -p), un --root
                         que no nombra ningún directorio, un autoload.php de composer
                         ausente, o un proveedor seleccionado
                         que no puede construirse — ya sea
                         $CANDY_CODE_PROVIDER o el proveedor persistido en
                         ~/.candy-code/config.json por Ctrl+P "Switch model".
                         Una ejecución one-shot nunca recurre al proveedor offline echo
                         cuando se seleccionó explícitamente un proveedor.
                         Un subcomando con un operando ausente o desconocido
                         (`session`, `mcp bogus`, `completion tcsh`) se reporta
                         aquí también.
  130/143/129             TUI: una señal detuvo el bucle — 128+N para
                         SIGINT (Ctrl+C), SIGTERM, SIGHUP; una salida
                         cooperativa (/exit, q) sigue saliendo con 0.

Ejemplos:
  candy-code -p "Explica la diferencia entre require e include"
  CANDY_CODE_PROVIDER=anthropic CANDY_CODE_MODEL=claude-sonnet-4-20250514 \
    candy-code -p "Escribe un hello world en Go"
  candy-code run "Escribe un hello world en Go"
  candy-code doctor
  candy-code models --output-format json | jq '.result.providers'
  eval "$(candy-code completion bash)"
  candy-code serve --port 7420

Para más información, consulta el README:
  https://github.com/detain/sugarcraft/tree/master/candy-code

