    'cli.references.redundant' => 'la entrada `references` {path} está dentro del espacio de trabajo de la sesión — la jaula ya la cubre, por lo que no se añade como segunda raíz de lectura.',
    'cli.references.unusable' => 'no se pudo leer una entrada `references` — debe ser un objeto con un `path` (o una cadena de ruta simple); esta entrada se omitió.',
    'cli.refuse.bad_mode' => '{source} es \'{value}\', que no es un modo de permiso (se esperaba uno de: {valid}). Se rechaza iniciar en lugar de recurrir al valor predeterminado permisivo.',
    'cli.refuse.claude_mcp_arg_entry' => 'claudeMcpArgs contiene una entrada no escalar; solo cadenas de argv',
