    'cli.refuse.claude_mcp_env_entry' => 'claudeMcpEnv debe mapear claves de cadena a valores de cadena',
    'cli.refuse.config_bom' => 'comienza con una marca de orden de bytes UTF-8, que JSON no permite — vuelve a guardar el archivo como UTF-8 sin BOM',
    'cli.refuse.config_dangling' => '{path} existe pero no es un archivo legible (es un enlace simbólico que no resuelve a uno). Se rechaza iniciar en lugar de ejecutar con una política de permisos desconocida.',
    'cli.refuse.config_is_directory' => '{path} existe pero no es un archivo legible (es un directorio). Se rechaza iniciar en lugar de ejecutar con una política de permisos desconocida.',
    'cli.refuse.config_not_json' => '{path} no es JSON utilizable ({error}). Se rechaza iniciar en lugar de ejecutar con una política de permisos desconocida.',
    'cli.refuse.config_not_object' => 'el nivel superior no es un objeto JSON',
    'cli.refuse.config_unreachable' => '{path} no es accesible: {reason}, por lo que no se puede saber si hay una política de permisos configurada. Se rechaza el inicio en lugar de ejecutar con una política de permisos desconocida.',
    'cli.refuse.config_unreadable' => '{path} existe pero no se pudo leer (verifique sus permisos). Se rechaza el inicio en lugar de ejecutar con una política de permisos desconocida.',
    'cli.refuse.dangling_directory' => '{dir} es un enlace simbólico que no resuelve a un directorio que este proceso pueda recorrer',
    'cli.refuse.foreign_owner' => '{path} pertenece al uid {uid}, no a la cuenta con la que se ejecuta esta sesión, por lo que la política de permisos y la cadena de hooks que contiene son de otro usuario. Se rechaza el inicio en lugar de ejecutar la política de otra cuenta.',
    'cli.refuse.hook_chain' => '{error} Se rechaza el inicio en lugar de ejecutar con una cadena de hooks que no es la configurada.',
    'cli.refuse.hooks_unreachable' => '{path} no es accesible: {reason}, por lo que no se puede saber si hay hooks configurados. Se rechaza el inicio en lugar de ejecutar con una cadena de hooks desconocida.',
    'cli.refuse.keybindings' => 'la configuración de keybindings no es utilizable: {reason}. Elimine la clave para ejecutar con los atajos incluidos (la referencia /keys los nombra). Se rechaza el inicio en lugar de ejecutar con reemplazos de teclas que no obtuvo.',
    'cli.refuse.max_cost_env' => '$CANDY_CODE_MAX_COST es \'{value}\', que no es un límite de gasto. Se esperaba un número positivo de dólares estadounidenses (decimales permitidos, se acepta un $ inicial), por ejemplo 5 o $2.50. Se rechazan cero y negativos en lugar de interpretarse como «sin límite» porque son la solicitud opuesta; una cifra demasiado grande para representarse (1e309, es decir, infinito) se rechaza porque instalaría un límite que nunca se activa. Desactive la variable para no tener límite. Se rechaza el inicio en lugar de ejecutar sin límite con un tope que usted solicitó.',
    'cli.refuse.max_cost_flag' => '--max-cost es \'{value}\', que no es un límite de gasto. Se esperaba un número positivo de dólares estadounidenses (decimales permitidos, se acepta un $ inicial), por ejemplo 5 o $2.50. Se rechazan cero y negativos en lugar de interpretarse como «sin límite» porque son la solicitud opuesta; una cifra demasiado grande para representarse (1e309, es decir, infinito) se rechaza porque instalaría un límite que nunca se activa. Omita la opción para no tener límite. Se rechaza el inicio en lugar de ejecutar sin límite con un tope que usted solicitó.',
    'cli.refuse.max_cost_setting' => 'maxCostUsd en su configuración es {value}, que no es un límite de gasto. Se esperaba un número positivo de dólares estadounidenses, por ejemplo 5 o 2.5. Elimine la clave para no tener límite. Se rechaza el inicio en lugar de ejecutar sin límite con un tope que usted solicitó.',
    'cli.refuse.max_turns_flag' => '--max-turns es \'{value}\', que no es un límite de pasos. Se esperaba un número entero positivo de pasos del bucle de herramientas, por ejemplo 8. Se rechaza cero en lugar de interpretarse como «sin límite» porque es la solicitud opuesta; una cifra demasiado grande para representarse se rechaza porque instalaría un límite que nunca se activa. Omita la opción para delegar en la configuración maxToolSteps. Se rechaza el inicio en lugar de ejecutar sin límite con un tope que usted solicitó.',
    'cli.refuse.no_home' => 'este proceso no puede determinar cuál es su directorio personal ($HOME no está definido, $USERPROFILE no está definido y no hay entrada en passwd para su uid), por lo que no se puede localizar la política de permisos ni la cadena de hooks en ~/.candy-code. Se rechaza el inicio en lugar de leer cualquiera de ellos desde un directorio de respaldo escribible por todos — exporte HOME a la cuenta a la que pertenece esta sesión.',
    'cli.refuse.no_project_root' => 'no se puede determinar la raíz del proyecto — el directorio de trabajo del proceso no está disponible (eliminado o ilegible). Pase --root <dir>.',
    'cli.refuse.not_searchable' => '{dir} no es recorrible por este proceso',
    'cli.refuse.project_settings_unusable' => '{path} no se pudo leer para obtener sus permissionRules ({reason}). Se rechaza el inicio en lugar de ejecutar con una política de permisos desconocida.',
    'cli.refuse.world_writable' => '{path} es escribible por todas las cuentas de esta máquina, por lo que la política de permisos y la cadena de hooks que contiene no son de este usuario. Se rechaza el inicio en lugar de ejecutar una política que cualquiera podría haber escrito — `chmod o-w {path}`.',
    'cli.selfupdate.channel_invalid' => '{value}: candy-code self-update --channel acepta stable o dev.',
