    'cli.selfupdate.check_up_to_date' => 'candy-code: actualizado — esta instalación es {current}, la última versión es {latest}.',
    'cli.selfupdate.composer_mode' => 'candy-code: self-update reemplaza una instalación phar, y esta copia se instaló mediante Composer — no hay un phar aquí que intercambiar. Actualícela con: {command} (una instalación global ejecuta `composer global update sugarcraft/candy-code` en su lugar).',
    'cli.selfupdate.composer_mode_root' => 'candy-code: self-update reemplaza una instalación phar, y esta copia es el paquete sugarcraft/candy-code instalado como raíz de Composer — no hay un phar aquí que intercambiar, y un paquete raíz no puede actualizarse a sí mismo mediante su propio comando de dependencia. Actualícelo con: {command} (el clon obtiene el nuevo código fuente y luego reconstruye el árbol vendor).',
    'cli.selfupdate.dir_not_writable' => 'candy-code: no se puede reemplazar el phar — el directorio {dir} no es escribible.',
