    'cli.selfupdate.rollback_failed' => 'candy-code: no se pudo restaurar {old} sobre {path}.',
    'cli.selfupdate.rollback_missing' => 'candy-code: no hay copia conservada que restaurar: {old} no existe (solo aparece tras una actualización exitosa).',
    'cli.selfupdate.rollback_restored' => 'candy-code: rollback restauró {old} sobre {path}; la copia conservada se consume, esta restauración es de un solo uso.',
    'cli.selfupdate.sidecar_malformed' => 'candy-code: el sidecar {asset} no es un sha256 de 64 dígitos hexadecimales en minúsculas para {phar}. No se intercambió nada.',
    'cli.selfupdate.sidecar_names' => 'candy-code: el sidecar nombra {found}, no {phar}. No se intercambió nada.',
    'cli.selfupdate.sig.deprecated' => 'candy-code: esta versión firma los bytes crudos del phar con {asset}; esa ruta heredada lee todo el artefacto en memoria y se acepta por un ciclo de versión más. Publique {replacement} — una firma Ed25519 sobre el cuerpo del sidecar sha256 — para que la verificación nunca salga del flujo.',
    'cli.selfupdate.sig.sidecar_invalid' => 'candy-code: {asset} no verifica el sidecar {sidecar} del {phar} descargado contra la clave de versión fijada. No se intercambió nada.',
    'cli.selfupdate.signature_invalid' => 'candy-code: {asset} no verifica el {phar} descargado contra la clave de versión fijada. No se intercambió nada.',
    'cli.selfupdate.signature_missing' => 'candy-code: esta versión no incluye {asset} ni {sig_sidecar}, y la clave de versión fijada requiere uno para {phar}. No se intercambió nada (--allow-unsigned es la omisión solo para dev).',
    'cli.selfupdate.staged_windows' => 'candy-code: la actualización está preparada para el intercambio al reiniciar — {new} se intercambia con {path} cuando este proceso termine; el progreso se registra en {path}.swap.log y la copia conservada permanece en {old}.',
    'cli.selfupdate.swap_leftover' => 'candy-code: un self-update anterior dejó un intercambio preparado en {new} que nunca se aplicó (su registro de intercambio documenta los intentos abandonados). Esta ejecución reemplaza la preparación antes de actualizar.',
    'cli.selfupdate.swap_spawn_failed' => 'candy-code: no se pudo iniciar el asistente de intercambio; los bytes verificados permanecen preparados en {new} y la copia en ejecución está intacta. Complete el renombrado a {path} manualmente, o vuelva a ejecutar self-update cuando nada retenga el archivo.',
    'cli.selfupdate.uncomparable' => 'candy-code: esta instalación informa {current}, que no es una versión de lanzamiento que self-update pueda ordenar.',
    'cli.selfupdate.unexpected_operand' => '{operand}: candy-code self-update no acepta operandos.',
    'cli.selfupdate.unsigned_allowed' => 'candy-code: --allow-unsigned omite la verificación de firma con clave fijada; el sidecar sha256 aún vincula estos bytes. Omisión para dev/pruebas — nunca un hábito de producción.',
    'cli.selfupdate.up_to_date' => 'candy-code: self-update: esta instalación ya es la última versión ({current}).',
    'cli.selfupdate.usage' => 'Uso: candy-code self-update [--check] [--rollback] [--allow-unsigned] [--channel=stable|dev]',
