    'cmd.mcp-auth.disable.done' => '✓ Desactivado `{server}` para esta sesión — las llamadas se rechazan desde el siguiente turno; el listado orientado al modelo no se re-deriva (ley de caché), por lo que sus herramientas siguen listadas hasta reiniciar.',
