    'cmd.mcp-auth.empty' => "Sin credenciales MCP almacenadas.\n\nLas credenciales son solo para servidores que exigen inicio de sesión OAuth; un\nservidor http declarado que no necesita ninguna funciona solo con su \"url\".\nLos servidores en sí se declaran bajo \"mcpServers\" en\n<project>/.mcp.json — receta: docs/MCP.md, \"{section}\".",
    'cmd.mcp-auth.enable.done' => '✓ Activado `{server}` para esta sesión — los rechazos de sesión se levantan desde el siguiente turno; las llamadas se enrutan de nuevo solo donde el enrutamiento de inicio ya permite el nombre.',
