    'cmd.mcp-auth.enable.persist-removed' => 'Eliminado `{server}` de la lista disabledMcpServers del usuario; el inicio ya no lo rechaza.',
    'cmd.mcp-auth.enable.unknown' => '! `{server}` no es un servidor MCP declarado de esta sesión — `/mcp list` muestra los nombres.',
    'cmd.mcp-auth.enable.usage' => 'Uso: /mcp enable <server> [--persist]',
    'cmd.mcp-auth.failed' => '✗ Registro fallido: {error}',
    'cmd.mcp-auth.heading' => '**Servidores MCP**',
    'cmd.mcp-auth.login-armed' => "↻ Inicio de sesión MCP iniciado para `{server}` — a la espera del enlace del navegador.\n\nEl proceso hijo vincula un puerto de loopback; complétalo en un navegador mientras la TUI sigue respondiendo. El cliente MCP de esta sesión memorizó su almacén al iniciar, por lo que el token surte efecto en el PRÓXIMO inicio; `/mcp list` muestra la credencial una vez almacenada.",
    'cmd.mcp-auth.login-busy' => '! Un inicio de sesión para `{server}` ya está en ejecución — termina o cancela ese primero (su URL y estado están en la transcripción de arriba).',
    'cmd.mcp-auth.login-code-delivered' => '✓ El callback fue entregado al inicio de sesión en espera para `{server}` — el proceso hijo completa el intercambio allí, y su resultado aparece en la transcripción.',
    'cmd.mcp-auth.login-code-refused' => '! No se pudo entregar el callback de inicio de sesión MCP para `{server}`: {reason}',
    'cmd.mcp-auth.login-code-reason-dial' => "el listener del inicio de sesión en espera no respondió",
    'cmd.mcp-auth.login-code-reason-host' => 'solo se aceptan los hosts de loopback `127.0.0.1` y `localhost`',
    'cmd.mcp-auth.login-code-reason-noslot' => 'ningún inicio de sesión para ese servidor está en espera actualmente en este host',
    'cmd.mcp-auth.login-code-reason-port' => 'el puerto no coincide con el puerto de callback que el inicio de sesión en espera anunció',
    'cmd.mcp-auth.login-code-reason-scheme' => 'la URL de callback debe usar el esquema `http` plano que el listener de inicio de sesión vincula',
    'cmd.mcp-auth.login-code-reason-shape' => 'el formato es `/mcp login <server> --code <callback-url>` con exactamente una URL',
    'cmd.mcp-auth.login-done' => '✓ Inicio de sesión MCP para `{server}` completado (salida {code}). Los tokens se adjuntan en el PRÓXIMO inicio — inicia una nueva sesión para que el permiso viaje en las peticiones; `/mcp list` actualiza el panel.',
    'cmd.mcp-auth.login-failed' => <<<'TXT'
✗ Inicio de sesión MCP para `{server}` terminó con {code} sin almacenar tokens.

Las últimas líneas del proceso hijo están arriba; el mismo flujo en un shell (`candy-code mcp auth login {server}`) imprime el error completo y es el lugar para depurar problemas de endpoint o puerto.
TXT,
    'cmd.mcp-auth.login-failed-spawn' => "✗ No se pudo iniciar el proceso hijo de inicio de sesión MCP para `{server}`.\n\nEjecuta la forma de shell directamente: `candy-code mcp auth login {server}`.",
    'cmd.mcp-auth.login-guidance' => "El inicio de sesión interactivo es un comando de shell, no un turno de chat:\n\n  candy-code mcp auth login <server> [token-url] [authorize-url] [registration-url]\n\nEjecuta el flujo de código de autorización OAuth con PKCE: tu navegador\ndevuelve el código a un listener de loopback en el shell, y los\ntokens almacenados se adjuntan a los servidores http coincidentes desde el siguiente inicio.",
    'cmd.mcp-auth.login-no-entry' => "✗ No se pudo encontrar el punto de entrada propio del programa para bifurcar `mcp auth login {server}`.\n\nEjecuta la forma de shell directamente: `candy-code mcp auth login {server}`.",
    'cmd.mcp-auth.login-served-armed' => "↻ Inicio de sesión MCP iniciado para `{server}` en el host SERVER — su enlace aparece abajo; ábrelo en un navegador en tu propia máquina. Tu navegador no puede alcanzar el listener de loopback del servidor directamente: cuando caiga en una página de error de conexión, copia la dirección de esa página y envía `/mcp login {server} --code <that-url>` para entregar el callback al inicio de sesión en espera. Los tokens se adjuntan en el SIGUIENTE inicio; `/mcp list` muestra la credencial una vez almacenada.",
    'cmd.mcp-auth.login-url' => '→ Abre esta URL para autorizar `{server}`:\n\n  {url}',
    'cmd.mcp-auth.not-found' => '! No se encontraron credenciales para `{server}`.',
    'cmd.mcp-auth.registered' => <<<'TXT'
✓ `{server}` registrado correctamente
ID de cliente: `{client}`
Las peticiones a un servidor MCP http con esta URL exacta ahora llevan este token automáticamente, renovado antes de caducar; los servidores iniciados antes de este comando lo toman en el siguiente inicio.
TXT,
    'cmd.mcp-auth.remove-usage' => 'Uso: mcp auth remove <server>',
    'cmd.mcp-auth.reconnect.auth' => '! `{server}` ahora informa que necesita un inicio de sesión OAuth.',
    'cmd.mcp-auth.reconnect.denied' => '! `{server}` es rechazado por un patrón de denegación.',
    'cmd.mcp-auth.reconnect.drifted' => "La configuración MCP cambió desde el inicio — reconexión rechazada. Una reconexión reinicia los servidores exactamente como `.mcp.json` los contiene ahora, mientras que esta sesión fue admitida contra los bytes que el inicio confió; iniciar entradas divergentes ejecutaría servidores que las decisiones de admisión nunca vieron. Reinicia la sesión para aplicar el cambio; esa es la única vía de aplicación.",
    'cmd.mcp-auth.reconnect.error' => 'Error al iniciar: {error}',
    'cmd.mcp-auth.reconnect.heading' => '**Servidores MCP reconectados**',
