    'cmd.mcp-auth.reconnect.state.up' => 'activo',
    'cmd.mcp-auth.reconnect.tool-drift' => 'ofrece {now} herramientas; esta sesión se construyó con {was} — el catálogo visible al modelo no se re-deriva a mitad de sesión, inicia una nueva sesión para adoptarlos',
    'cmd.mcp-auth.reconnect.unknown' => 'Esta sesión no registró un resumen de inicio para `.mcp.json`, así que una reconexión no puede probar que la configuración aún contiene los bytes desde los que el inicio arrancó — rechazado, reiniciar es la única vía de aplicación.',
    'cmd.mcp-auth.removed' => '✓ Credenciales de `{server}` eliminadas',
