    'cmd.mcp-auth.status.expiring' => '● caduca pronto',
    'cmd.mcp-auth.status.none' => '○ sin credenciales',
    'cmd.mcp-auth.undiscovered' => "! No se pudieron descubrir los endpoints OAuth de `{server}`.\n\nProporcionales explícitamente:\n  `mcp auth add {server}` *<registration-url>* *<token-url>*\n\nNo haber nada que descubrir suele significar que no hay nada que registrar: un\nservidor que no requiere inicio de sesión funciona solo con su \"url\" una vez\ndeclarado en .mcp.json (docs/MCP.md, \"{section}\").",
    'cmd.mcp-auth.unknown' => 'Subcomando desconocido \'{sub}\'. Usa: list, add, remove, login, reconnect, enable, disable',
    'cmd.mcp-auth.usage' => "Uso:\n  mcp auth list                    — listar servidores registrados\n  mcp auth add <server> [reg-url] [token-url]  — almacenar credenciales OAuth de un servidor\n  mcp auth remove <server>         — eliminar las credenciales de un servidor\n  mcp auth login <server>          — imprimir el comando de shell para inicio de sesión interactivo\n  /mcp reconnect                   — reiniciar los servidores declarados, solo mientras .mcp.json aún coincida con el inicio\n  /mcp enable <server> [--persist]   — levantar el rechazo de esta sesión a un servidor declarado\n  /mcp disable <server> [--persist]  — rechazar las llamadas de un servidor declarado en esta sesión",
    'cmd.mcp.description' => 'Gestionar la autenticación de servidores MCP (list/add/remove; login imprime el comando CLI) y habilitar/deshabilitar en sesión',
