    'sandbox.hook.not_run' => 'No ejecutado: el hook `{hook}` está encauzado en el sandbox `{mode}` por sandboxScope, pero el sandbox {name} no puede iniciarse en este host ({reason}). No se ejecutó nada, en sandbox ni de otro modo. Informe al usuario: puede arreglar {name} ({remedy}) o establecer bashSandbox en "off".',
    'sandbox.lsp.not_started' => 'No iniciado: el servidor de lenguaje `{language}` ({command}) está encauzado en el sandbox `{mode}` por sandboxScope, pero el sandbox {name} no puede iniciarse en este host ({reason}). No se inició nada, enjaulado ni de otro modo. Informe al usuario: puede arreglar {name} ({remedy}), establecer bashSandbox en "off", o eximir este servidor con `"sandbox": false` en su propia entrada `lsp`.',
    'sandbox.mcp.not_started' => 'No iniciado: el servidor MCP `{server}` está encauzado en el sandbox `{mode}` por sandboxScope, pero el sandbox {name} no puede iniciarse en este host ({reason}). No se inició nada, enjaulado ni de otro modo. Informe al usuario: puede arreglar {name} ({remedy}), establecer bashSandbox en "off", o eximirlo con `"sandbox": false` en su entrada de nivel de usuario.',
    'sandbox.mcp.opt_out_ignored' => 'Ignorado: la exclusión `"sandbox": false` en el/los servidor(es) MCP {servers} no proviene del archivo de ajustes de usuario — solo el nivel de usuario puede eximir un servidor stdio de la jaula sandboxScope. El/los servidor(es) se enjaulan según el alcance.',
    'sandbox.runner.skipped' => 'Omitido: la ejecución {scope} está encauzada en el sandbox `{mode}` por sandboxScope, pero el sandbox {name} no puede iniciarse en este host ({reason}). No se ejecutó nada, en sandbox ni de otro modo. Informe al usuario: puede arreglar {name} ({remedy}) o establecer bashSandbox en "off".',
