    'chat.command.error' => '**Error:** {error}',
    'chat.compact.idle_advisory' => 'Esta sesión ha estado inactiva más de una hora y ha crecido a ~{tokens} tokens estimados, superando su ventana de contexto de {limit} tokens. Ejecuta /compact para reducir el contexto antes de continuar. Enviar otro mensaje no lo enviará tal cual: el siguiente turno supera el nivel de compactación automática, así que los intercambios antiguos se resumen primero, y el turno se rechaza outright si eso no libera suficiente.',
    'chat.compact.idle_auto_scheduled' => 'Compactación automática por inactividad: la sesión superó la ventana de inactividad con la transcripción por encima de su nivel de compactación (~{tokens} tokens estimados contra una ventana de {limit} tokens), así que la solicitud de resumen se envió sin intervención. El pliegue aterriza en el siguiente turno; nada se factura dos veces y no se envía respuesta a nadie.',
    'chat.compact.idle_folded' => 'Compactado durante la inactividad: ~{before} tokens estimados pasaron a ~{after}. `compaction.idleAuto` ejecutó el nivel automático mientras la sesión permanecía intacta, así que los intercambios que condensó son ahora resúmenes.',
