    'chat.title.error' => '**Error:** {error}',
    'chat.turn.loop_guard' => 'Este turno fue terminado por el guard de bucle de llamadas repetidas: el modelo llamó a {tool} {count} veces con los mismos argumentos y obtuvo el mismo resultado cada vez. La respuesta de arriba describe dónde se detuvo. Apúntelo a un enfoque diferente, o escriba `continue` una vez que algo haya cambiado.',
    'chat.turn.output_limit' => 'El proveedor detuvo esta respuesta en su límite de salida, así que el texto de arriba puede terminar a medias. Aumente `maxOutputTokens` en ~/.candy-code/config.json para una respuesta más larga, o pida el resto en su siguiente mensaje.',
    'chat.turn.steps_exhausted' => 'Este turno agotó todos sus pasos de herramientas antes de terminar el trabajo, así que la respuesta de arriba describe dónde se detuvo — lo que está terminado y lo que queda — no una respuesta completa. Escriba `continue` para retomarlo desde ahí, o suba el techo para turnos agénticos más largos — la bandera --max-turns en el arranque tiene prioridad sobre el ajuste `maxToolSteps` en ~/.candy-code/config.json, así que suba el que esté en vigor.',
    'chat.turn.unpriced_model' => 'Esta aplicación no tiene precio registrado para el modelo `{model}`, así que este turno facturó $0.00 como límite inferior, no como llamada gratuita — los totales de gasto y el tope de gasto quedan subestimados hasta que exista una tarifa. Declare una bajo `modelPrices` en ~/.candy-code/config.json (USD por 1M tokens, claves `input` y `output`) para fijarle precio.',
