    'host.agents.accept.bad_name' => '`{name}` no es un nombre de borrador. Un borrador es un archivo directamente bajo el directorio de borradores, y se pasa su nombre — letras minúsculas, dígitos, puntos, guiones bajos y guiones — a /agents accept.',
    'host.agents.accept.exists' => 'Ya existe un preajuste llamado {name} bajo {dir}/, y /agents accept nunca sobrescribe un preajuste activo. Elimine o renombre ese preajuste primero, o /agents new un borrador con otro nombre.',
    'host.agents.accept.frontmatter' => 'El borrador {name} no tiene un bloque de frontmatter que se analice como un mapeo, así que no se promovió. Ejecute /agents new de nuevo, o corrija el archivo y acéptelo otra vez.',
    'host.agents.accept.missing' => 'No hay borrador llamado {name} bajo {dir}/. Ejecute /agents new para crear uno, o /agents proposed para listar los borradores.',
