    'host.agents.accept.type' => 'El borrador {name} declara `{key}` como un valor que el lector de preajustes no puede tipar — espera una cadena o una lista de cadenas.',
    'host.agents.accept.unknown' => 'El borrador {name} declara `{key}`, una clave sobre la que ningún lector de preajustes actúa{hint}. Elimínela o corrija la ortografía; /agents accept solo promueve archivos cuyas claves este port lee.',
    'host.agents.error' => 'El comando /agents draft falló: {error}',
    'host.agents.new.dispatched' => 'Pidiendo al agente que redacte un preajuste de esta conversación; solo escribe en el nivel de borrador, y nada se promueve hasta que ejecute /agents accept.',
    'host.agents.proposed.heading' => 'Borradores de agentes propuestos:',
