    'host.agents.usage' => 'Uso: /agents [list|<name>|use <preset|default>|new <focus>|proposed|accept <name>]',
    'host.agents.not_configured' => 'Gestor de agentes no configurado — no hay runtime de sub-agente adjunto a esta ejecución, por lo que /agents no puede iniciar ni vigilar agentes. Una ejecución simple de `candy-code` siempre tiene uno; una compilación de integración con host debe adjuntarlo.',
