    'host.agents.use_switched' => '{name} es ahora el agente principal de esta sesión — sus herramientas, modelo y nivel mínimo de permisos se mantienen hasta que cambies; un reinicio ejecuta el valor predeterminado de sesión simple.',
    'host.agents.use_turn_running' => 'Hay un turno en ejecución — el agente principal cambia entre turnos, como un cambio de modo de permisos.',
