    'host.command_shell.bundle_refused' => '[!`{command}` no se ejecutó: /{name} proviene de un bundle de plugin, un paquete empaquetado por otra persona. Una fila de bundle rechaza formas de shell a menos que indique el nombre del bundle bajo "trustedBundleCommands" en su propia configuración de usuario — y esa autorización solo cuenta para bundles de nivel de usuario: un checkout de proyecto no puede otorgarse shell a sí mismo, ni siquiera usurpando un nombre listado — el resto del comando fue enviado.]',
    'host.command_shell.mcp_refused' => '[!`{command}` no se ejecutó: /{name} es un prompt MCP obtenido de un servidor, texto que llegó por la red. Un cuerpo obtenido rechaza formas de shell independientemente de lo que este proyecto confíe — indique la clave del servidor bajo "mcpPromptShell" en su propia configuración de usuario para permitir que sus formas de shell lleguen a la puerta de permisos — el resto del prompt fue enviado.]',
    'host.loop.not_configured' => 'Programaciones no configuradas en esta sesión — /loop no tiene reloj sobre el que ejecutar. Una ejecución simple de `candy-code` siempre lleva uno; una compilación de integración con host debe proporcionarlo.',
    'host.loop.usage' => 'Uso: /loop <interval> <prompt> — intervalo como 90s, 15m, 2h, 1d (mínimo 10s). El bucle vive en este proceso; /schedules lo lista, /schedules delete lo termina.',
