    'host.output_style.column_style' => 'Estilo',
    'host.output_style.empty' => "No se encontraron estilos de salida.\nUn estilo es un archivo markdown en ~/.candy-code/styles/ (o .candy-code/styles/ en el proyecto),\nnombrado por su nombre de archivo: terse.md se selecciona con /output-style terse.",
    'host.output_style.footer' => "/output-style <name> selecciona un estilo; exactamente uno viaja a la vez, y un\ncambio borra el anterior. /output-style off borra la ranura. `off` es una\npalabra reservada — un archivo llamado off.md no puede seleccionarse. Un estilo deshabilitado por su\npropio frontmatter (`enabled: false`) queda fuera del prompt sin importar cómo se nombre.",
