    'host.schedules.not_configured' => 'Programaciones no configuradas en esta sesión.',
    'host.schedules.usage' => 'Uso: /schedules [list] | add <name> <interval> <prompt> [--mode <mode>] [--provider <name>] [--heartbeat] | enable <name> | disable <name> | delete <name>. Las filas viven en ~/.candy-code/schedules.json; /schedules add crea una a través de los límites de la fábrica de la herramienta Schedule, /loop registra una efímera.',
    'host.schedules.none' => 'Sin programaciones. /schedules add <name> <interval> <prompt> crea una a través de los mismos límites que la herramienta Schedule, o escribe una fila en ~/.candy-code/schedules.json (`name`, `every` en segundos, `prompt`, `root` — el directorio del proyecto donde se dispara; opcionales `provider`, `permissionMode` (las grafías de clase bypass se rechazan; déjalo fuera para el nivel mínimo no interactivo), `enabled`, `timeoutSeconds`, `kind` (`task` responde, `heartbeat` puede permanecer en silencio)), o /loop una para esta sesión. docs/SCHEDULES.md es el formato.',
