    'host.compact.thrash' => 'La compactación de contexto se ejecutó {times} veces seguidas y el transcript volvió a superar el límite cada vez, así que este prompt no se envió y no se intentó más compactación. Los intercambios recientes que la reescritura mantiene completos son los que no caben — recorta el mayor de ellos (la salida de herramientas suele ser la mayor parte), o empieza de nuevo con /rewind o /clear. /model con una ventana de contexto mayor también resuelve esto.',
    'host.compact.tier_report' => 'El contexto alcanzó el nivel de compactación automática, así que los intercambios más antiguos se resumieron: {before} mensajes -> {after} mensajes, ~{saved}% del conteo estimado de tokens liberado (~{tokens} tokens estimados ahora, contra una ventana de contexto de {limit} tokens).',
    'host.compact.truncated.one' => '{count} mensaje alcanzó {tier} por sí solo, así que se truncó para caber en la ventana de contexto en lugar de rechazar el turno: ~{tokens} tokens estimados ahora, contra una ventana de contexto de {limit} tokens. El texto que se envía al modelo lleva un marcador donde fue cortado; tu original completo permanece en el transcript, oculto al modelo.',
    'host.compact.truncated.other' => '{count} mensajes alcanzaron {tier} por sí solos, así que se truncaron para caber en la ventana de contexto en lugar de rechazar el turno: ~{tokens} tokens estimados ahora, contra una ventana de contexto de {limit} tokens. El texto que se envía al modelo lleva un marcador donde cada uno fue cortado; tus originales completos permanecen en el transcript, ocultos al modelo.',
