    'host.spend.usage' => 'Uso: /budget <amount> para limitar el gasto de esta sesión (p. ej. /budget 5 o /budget $2.50), /budget off para eliminarlo, /budget solo para ver dónde estás. La cantidad debe ser un número real mayor que cero — un límite de 0 y sin límite son peticiones opuestas, así que `0` se rechaza en lugar de adivinar, y una cifra demasiado grande para representarse (`1e309`, que es infinito) se rechaza en lugar de aceptarse como un límite que nunca se activaría.',
