    // --- fix-tui-interact 2026-10-14 ---
    'tui.picker.notice.slash_filter' => '`{word}` parece un comando de barra, no un filtro — Intro aquí reanudaría la mejor coincidencia. Pulsa Escape y escribe el comando en la entrada.',
    'tui.app.stop_all_armed' => 'A punto de detener todos los agentes en ejecución — pulsa "s" de nuevo en 3 s para confirmar.',

    // --- fix-app-launch 2026-10-14 ---
    'appLaunch.doctor.mbstring_missing' => 'falta — los cálculos de ancho de fotograma (mb_*) no pueden ejecutarse; reinstala PHP con ext-mbstring',
    'appLaunch.doctor.intl_missing' => 'falta — los cálculos de ancho de grafema/IntlChar no pueden ejecutarse; reinstala PHP con ext-intl',
    'appLaunch.notice.policy_changed' => '⚠ config.json o hooks.yaml han cambiado desde la última ejecución. Los nuevos hooks del proyecto quedan en cuarentena solo para esta ejecución — revisa ~/.candy-code/config.json y hooks.yaml, y se aplicarán',
    'appLaunch.notice.project_policy_changed' => '⚠ El hooks.yaml de un proyecto de confianza contiene entradas que la última ejecución no vio. Los nuevos hooks del proyecto quedan en cuarentena solo para esta ejecución — revisa el .candy-code/hooks.yaml de ese repositorio, y se aplicarán',
    'appLaunch.notice.bypass_mode' => '⚠ El modo de permisos es bypass-permissions: cada llamada a herramienta se ejecuta sin confirmación. Cámbialo con /permissions (TUI), --permission-mode, o establece un modo de permisos distinto en ~/.candy-code/config.json',
    // C-SEC-7.a: `-p` now defaults to the ASKING mode, so an unattended scripted
    // run that named no mode starts refusing — the launch says so once, and names
    // the one-flag fix. No trailing period — STDERR_LINE_FORMAT adds one
    // (LaunchNoticeOwnPeriodTest).
    'appLaunch.notice.headless_default' => 'ℹ -p inicia en modo de permisos default: una ejecución desatendida rechaza cada llamada a herramienta que pediría confirmación. Pasa --permission-mode (bypass-permissions ejecuta todo) para ejecuciones con script',
    // C-SEC-7.e (owner ruling t212, option 3): the implicit autoReview default
    // announces once per session the first time it engages — de-duped by message
    // identity in the launch-notices store, like the bypass banner. Names the
    // opt-out and owns up to the money. No trailing period — STDERR_LINE_FORMAT
    // adds one (LaunchNoticeOwnPeriodTest).
    'appLaunch.notice.auto_review_default' => '⚠ autoReview está activado por defecto para esta ejecución: las llamadas de modo auto marcadas son revisadas por el modelo de título, y cada revisión es una llamada de modelo de pago. Establece autoReview a false en ~/.candy-code/config.json para desactivarlo',
    // C-SEC-6.b: names the file, what it added, and what could not be honoured.
    // No trailing period — STDERR_LINE_FORMAT adds one (LaunchNoticeOwnPeriodTest).
    'appLaunch.notice.project_narrowing_rules' => '⚠ {file} redujo los permisos de esta ejecución: {count} regla(s) de denegar/pedir cargadas primero, {dropped} regla(s) de permitir descartadas — un archivo de proyecto no puede conceder permitir',
    'appLaunch.notice.restricted' => '⚠ --restricted: esta ejecución se realiza sin herramientas de ejecución de código — Bash, PtyRun, Task, Workflow, ShellStop y mcp_call están ausentes de cada conjunto orientado al modelo; las herramientas de archivo permanecen bajo su confinamiento de ruta y /permissions no puede devolver las herramientas descartadas',
    'appLaunch.notice.safe_mode' => '⚠ --safe-mode: las raíces de proyectos de confianza, bundles, y skills, comandos y agentes externos se ignoran todos para esta ejecución — se comporta como si nada hubiera sido nunca de confianza',

    // --- fix-w2-chat 2026-10-14 ---
    'chat.launch.echo_backend' => 'No hay proveedor configurado, así que esta sesión se ejecuta con el backend de eco offline integrado — las respuestas se repiten localmente, no se llama a ningún modelo. Ejecuta `candy-code doctor` para ver qué necesita un proveedor, y luego pulsa Ctrl+P para cambiar de modelo una vez configurado uno.',
    'keys.chat.repaint' => 'Borrar la pantalla y repintar el fotograma',
    'keys.unbound' => 'sin asignar',

    // --- C-EXT-1 (Claude Code hook dialect) 2026-10-27 ---
    'hooks.notice.advisory' => '⚠ El hook `async` de Claude Code `{hook}` terminó con {code}. Un hook `async` pide observar una llamada a herramienta en lugar de filtrarla, así que no tiene poder para bloquearla y la llamada continuó. Lo que dijo: {reason}',
    'hooks.notice.claude_dialect' => '⚠ El hook de Claude Code `{hook}` terminó con {code}, lo cual Claude Code interpreta como una queja no bloqueante en lugar de una decisión, así que la llamada a herramienta continuó. Lo que dijo: {reason}',
    'hooks.notice.said_nothing' => '(nada en stderr)',
    'hooks.notice.system_message' => '⚠ El hook `{hook}` te dejó un mensaje: {message}',

    // --- C-EXT-6.c (type: http hooks) 2026-10-30 ---
    // Every row names the hook and scheme://host only: never a path, a query,
    // or any header value, so an Authorization cannot ride out of the process
    // inside its own refusal.
    'hooks.http.deny_bad_url' => 'El hook HTTP `{hook}` está configurado con una URL que no se puede usar ({reason}); el destino mostrado es {target}. Un hook que no puede indicar a dónde va no ha aprobado esta llamada.',
    'hooks.http.deny_scheme' => 'El hook HTTP `{hook}` indica {target}, que no es una URL http o https. candy-code marca hooks solo por esos dos esquemas, y la llamada se rechaza en lugar de ejecutarse contra un transporte que nadie ha verificado.',
    'hooks.http.deny_credentials' => 'El hook HTTP `{hook}` lleva credenciales en su URL ({target}). Una contraseña escrita en una URL acaba en registros y proxies, por lo que se rechaza aquí; envíala como una cabecera cuyo valor lea un nombre de `allowedEnvVars` en su lugar.',
    'hooks.http.deny_blocked_target' => 'El hook HTTP `{hook}` no puede ser consultado: {reason} ({target}). Las direcciones privadas y link-local se rechazan por la misma regla que una fetch saliente, y un guardián al que nunca se llegó no ha aprobado esta llamada.',
    'hooks.http.deny_unanswered' => 'El hook HTTP `{hook}` no respondió ({reason}); el destino era {target}. Un hook al que no se pudo contactar no ha aprobado esta llamada, por lo que se rechaza.',
    'hooks.http.deny_header_injection' => 'El hook HTTP `{hook}` no puede enviar su cabecera `{field}`: el nombre o su valor contiene un carácter de control, que es encuadre de solicitud, no un valor de cabecera. No se envió nada a {target} y la llamada se rechaza.',
    'hooks.http.notice_unanswered' => '⚠ El hook HTTP `{hook}` no respondió ({reason}), por lo que no pudo condicionar la llamada. Se le consultó en {target}.',
    'hooks.http.reason_unreachable' => 'la conexión o la solicitud agotó su tiempo de espera dentro del timeout propio del hook',
    'hooks.http.reason_oversized' => 'la respuesta superó {bytes} bytes y no terminó en ninguna parte',
    'hooks.http.reason_no_status' => 'la respuesta no contenía línea de estado HTTP',
    'hooks.http.reason_redirect' => 'hubo una redirección, y una llamada de hook no sigue redirecciones',
    'hooks.http.reason_status' => 'la respuesta no fue un estado 2xx',


    // --- C-EXT-6.d (type: prompt hooks) 2026-10-31 ---
    // Nothing was dialled and nothing was spent when these fire, so no row
    // carries a {target}: the hook either has no backend to be asked on, or
    // the answer it got is not a verdict.
    'hooks.prompt.deny_unanswered' => 'El hook de prompt `{hook}` no respondió ({reason}). Un hook cuyo veredicto nunca se devolvió no ha aprobado esta llamada, por lo que se rechaza.',
    'hooks.prompt.notice_unanswered' => '⚠ El hook de prompt `{hook}` no respondió ({reason}), por lo que no pudo condicionar la llamada.',
    'hooks.prompt.reason_call_failed' => 'no se pudo consultar al modelo',
    'hooks.prompt.reason_empty_verdict' => 'El hook de prompt `{hook}` denegó esta llamada sin dar motivo.',
    'hooks.prompt.reason_no_backend' => 'este lanzamiento no tiene backend de título al que consultar',
    'hooks.prompt.reason_no_prompt' => 'la entrada lleva un prompt vacío que consultar',
    'hooks.prompt.reason_unparseable' => 'su respuesta no fue el único objeto JSON con un booleano `ok` que debe devolver',

    // --- settings help (W3-B i18n migration) ---
    'settings.advisorModel.help' => 'Modelo que la herramienta `Advisor` consulta para una segunda opinión; sin definir —el predeterminado— no ofrece la herramienta en absoluto (no hay alternativa de modelo barato: el punto es un modelo que tú elegiste).',
    'settings.allowedTools.help' => 'Lista blanca de nombres de herramientas o globs; sin definir ofrece todas las herramientas.',
    'settings.attribution.help' => '{"commit": "…", "pr": "…"}: el pie y la línea de PR que la guía de git solicita.',
    'settings.autoCommit.help' => 'off, turn (un commit por turno, mensaje del modelo de título) o edit (uno por Write/Edit); /undo lo revierte.',
    // C-SEC-7.e (owner ruling t212, option 3): the help states the implicit
    // default, the once-per-session announce, and the paid-call fact.
    'settings.autoReview.help' => 'Bajo auto, una llamada que el clasificador de seguridad marca (salvo un hallazgo de seguridad, que siempre pregunta) la revisa el modelo de título, que la permite, te pregunta o la deniega. Activado por defecto siempre que existe un modelo revisable, y un lanzamiento que activa ese predeterminado lo indica una vez; pon false para excluirte. Cada revisión es una llamada de modelo de pago.',
    'settings.autoReviewModel.help' => 'El `provider/model` en el que se ejecuta el revisor automático, por ejemplo `openai/gpt-4.1-mini`; vacío significa el modelo de título. Un proveedor que no se puede construir deja el revisor apagado con una advertencia de lanzamiento.',
    'settings.autoReviewScope.help' => 'Lo que `autoReview` envía al revisor: `shell` (el predeterminado) es cada comando de shell no de solo lectura que la lista de patrones pasó; `writes` también revisa `Edit`, `Write`, `ApplyPatch` y `WebFetch`, con el diff pendiente para las herramientas de escritura; `all` revisa cada llamada que la lista pasó. Cualquier otra grafía se comporta como `shell`. Cada revisión es una llamada de modelo de pago.',
    'settings.autoTest.help' => 'Tras un turno que editó un archivo, ejecuta `testCommand`; en caso de fallo la salida vuelve al modelo, como máximo 3 veces por turno.',
    'settings.bashInteractiveIdleSeconds.help' => 'Segundos que una ejecución de Bash con `interactive: true` puede no imprimir nada antes de detenerse por esperar una pulsación.',
    'settings.bashMaxTimeoutSeconds.help' => 'El `timeout` máximo que un comando Bash puede solicitar; valores mayores se recortan a él.',
    'settings.bashSandbox.help' => 'En Linux, Bash se ejecuta dentro de bubblewrap; en macOS, dentro de un perfil Seatbelt mediante `sandbox-exec` — escribible solo en la raíz de trabajo (`no-network` también corta la red). `allowlist` (Linux) enruta el tráfico de salida por el proxy de egreso del lanzamiento, que solo concede los hosts listados en `sandboxAllowedDomains`: con la lista EMPTY predeterminada se comporta EXACTAMENTE como `no-network` hasta que listes hosts, e incluso una vez listados, el tráfico no HTTP (ssh, puertos de base de datos) y cualquier host que no hayas listado fallan. En macOS, `allowlist` se aplica como `no-network`. Rechaza comandos cuando la jaula no puede iniciarse; un valor no reconocido significa `no-network`, nunca `off`.',
    'settings.bashSandboxNestedUserns.help' => 'Pon `true` para permitir que un comando `Bash` enjaulado cree su propio espacio de nombres de usuario, lo que rootless podman o buildah y una jaula de Chromium necesitan. El valor predeterminado `false` ejecuta bubblewrap con `--unshare-user --disable-userns`, bloqueando la vía habitual de escape de una jaula de montaje; en un host cuyo bubblewrap es demasiado antiguo para esas opciones, la jaula ejecuta el conjunto simple y su propia descripción lo indica.',
    'settings.bashTimeoutSeconds.help' => 'Segundos que un comando Bash puede ejecutarse cuando el modelo no pasa `timeout`; nunca por encima del techo de Bash.',
    'settings.chatToolTimeoutSeconds.help' => 'Presupuesto de tiempo real de un lote de llamadas de herramientas que la ruta nativa de chat (proveedor `command`) bifurca; los rezagados se eliminan.',
    'settings.claudeMcpArgs.help' => 'Argumentos para ese binario; sin definir usa el predeterminado del transporte.',
    'settings.claudeMcpBinary.help' => 'Ruta absoluta del binario `claude` que el transporte claude-mcp puede lanzar.',
    'settings.claudeMcpEnv.help' => 'Variables de entorno literales entregadas a ese binario.',
    'settings.compaction.autoPercent.help' => 'Proporción de ventana en la que los intercambios antiguos se condensan automáticamente antes de enviar el prompt.',
    'settings.compaction.autoTokens.help' => 'Límite absoluto del nivel automático y del presupuesto de pasos por turno. 0 desactiva el límite.',
    'settings.compaction.blockPercent.help' => 'Proporción de ventana más allá de la cual se rechaza un prompt hasta liberar espacio; el único nivel que rechaza.',
    'settings.compaction.blockTokens.help' => 'Límite absoluto del nivel de bloqueo; sin definir por defecto. Establecerlo permite que un límite rechace prompts.',
    'settings.compaction.idleAuto.help' => 'Compactar una sesión inactiva por encima del nivel durante la inactividad en lugar de esperar al siguiente prompt, usando la maquinaria del nivel automático (se aplican el tope de gasto y el cortacircuitos). off: nunca; hour: tras la ventana completa de compaction.idleOfferSeconds; cacheTtl: justo antes de la caducidad de la caché de prompt del proveedor — una hora cuando el proveedor marca puntos de ruptura de caché, unos 5 min para cachés del lado del servidor, nunca donde no informa nada en caché — una vez que el historial supera un suelo por debajo del nivel automático, porque el siguiente prompt de otro modo precargaría toda la conversación sin caché; en el tick de 60 segundos una caché de 5 min se pliega a unos 4 minutos de inactividad. Cuesta una llamada de proveedor en segundo plano; requiere compaction.idleOfferSeconds mayor que 0. Un bool sigue leyéndose: true significa hour, false significa off.',
    'settings.compaction.idleOfferSeconds.help' => 'Una sesión que superó toda su ventana de contexto y estuvo intacta este tiempo se ofrece /compact en lugar de enviar el prompt. 0 nunca ofrece.',
    'settings.compaction.keepRecent.help' => 'Intercambios usuario/asistente más recientes que una compactación conserva íntegros.',
    'settings.compaction.mode.help' => 'llm: el modelo de resumen escribe los resúmenes (la heurística es su alternativa); heuristic: resúmenes locales de una línea, nunca una llamada de modelo; off: nada se compacta solo, /compact sigue funcionando y el nivel de bloqueo sigue rechazando.',
    'settings.compaction.modelTokenCaps.help' => '{"<model>" or "<provider>/<model>": {"reminderTokens", "autoTokens", "blockTokens"}} que sobrescribe los tres límites; 0 borra uno.',
    'settings.compaction.refillLimit.help' => 'Compactaciones automáticas consecutivas que pueden volver a superar su nivel, con el prompt sin enviar, antes de que el siguiente prompt se rechace en lugar de compactarse de nuevo.',
    'settings.compaction.reminderPercent.help' => 'Proporción de ventana en la que el recordatorio «considera compactar» y el resumen en segundo plano anticipado comienzan; por debajo del nivel automático.',
    'settings.compaction.reminderTokens.help' => 'Límite absoluto del nivel de recordatorio: se dispara en min(percentage, this). 0 desactiva el límite.',
    'settings.compaction.summaryAssistantChars.help' => 'Respuestas del asistente más largas que esto se convierten en "[exchanged information]" en una línea de resumen heurístico.',
    'settings.compaction.summaryUserChars.help' => 'Caracteres de un mensaje de usuario que la línea de resumen heurístico conserva.',
    'settings.compaction.toolOutputChars.help' => 'Caracteres de la mitad del asistente de un intercambio condensado que se muestran al modelo de resumen.',
    'settings.connectTimeoutSeconds.help' => 'Límite para alcanzar un host del proveedor (DNS, TCP, TLS); no es un timeout de solicitud.',
    'settings.contextPruning.compress.help' => 'manual ofrece Compress solo en un turno que inicias con /compress, una llamada; auto lo ofrece en cada turno donde el modelo puede recortar.',
    'settings.contextPruning.iterationNudgeThreshold.help' => 'Resultados de herramientas desde el último prompt tras los cuales un bucle largo de herramientas se recuerda recortar.',
    'settings.contextPruning.maxContextTokens.help' => 'Tamaño de contexto por encima del cual la fila más reciente lleva el recordatorio más fuerte «recorta ahora».',
    'settings.contextPruning.minContextTokens.help' => 'Tamaño de contexto por debajo del cual nunca se recuerda al modelo recortar; no debe exceder el tamaño del recordatorio duro.',
    'settings.contextPruning.mode.help' => 'auto recorta filas obsoletas al inicio de cada turno; manual solo con /sweep; off no muestra etiquetas de referencia. /pruning lo sobrescribe por sesión.',
    'settings.contextPruning.nudgeFrequency.help' => 'Filas nuevas que un recordatorio espera tras el último, para no repetirse en cada paso.',
    'settings.contextWindow.help' => 'Sobrescritura de ventana de tokens: un recuento para el modelo del proveedor, o {"<model>": tokens}.',
    'settings.debug.commands.help' => 'Imprime cada directorio o archivo de comando personalizado rechazado en stderr, no solo el recuento de una línea del lanzamiento.',
    'settings.debug.rules.help' => 'Imprime cada directorio o archivo de reglas rechazado en stderr.',
    'settings.debug.skills.help' => 'Imprime cada archivo de skill omitido y directorio de skills rechazado en stderr, no solo el recuento de una línea del lanzamiento.',
    'settings.debug.stream.help' => 'Imprime la línea "onToken observer threw, detaching it" en stderr cuando el sumidero de streaming de un integrador falla a mitad de turno.',
    'settings.diffPreviewRows.help' => 'Filas de un diff de Edit o Write mostradas en la transcripción antes de que el resto se resuma.',
    'settings.diffStyle.help' => 'Diseño de diffs en la transcripción: `auto` pinta los hunks lado a lado en terminales anchos (120 columnas o más) y unificado en el resto, `unified` siempre una columna, `split` siempre dos. Los cuerpos de diff se tiñen por token en ambos diseños; la columna de marcadores `+`/`-` conserva su color.',
    'settings.disabledMcpServers.help' => 'Nombres de servidores de `.mcp.json` o globs (`untrusted_*`) que nunca se inician, listan ni llaman, para el agente principal y cada sub-agente.',
    'settings.disabledRules.help' => 'Paquetes de reglas de nivel de usuario excluidos del prompt desde el primer turno.',
    'settings.disabledSkills.help' => 'Skills eliminadas del descubrimiento; también gana sobre enabledSkills.',
    'settings.disabledTools.help' => 'Nombres de herramientas o globs eliminados del conjunto de herramientas visible al modelo.',
    'settings.doubleEscSeconds.help' => 'Qué tan rápido debe seguir el segundo Esc al primero para cancelar un turno en ejecución.',
    'settings.embeddingModel.help' => 'Modelo de embeddings para el recuerdo de memoria por turno; sin definir ordena las notas solo por palabra clave.',
    'settings.enabledSkills.help' => 'Skills cuyos cuerpos completos viajan en el prompt de sistema cada turno.',
    'settings.env.diffMaxBytes.help' => 'Bytes que cada una de las dos secciones de git diff conserva antes de truncarse con una nota.',
    'settings.env.gitDiffAfterWrites.help' => 'Tras un paso que escribió archivos, muestra los diffs de git en staged y unstaged en el contexto del turno.',
    'settings.expandToolOutput.help' => 'Muestra la salida completa de cada llamada de herramienta terminada en la transcripción; Ctrl+O o un clic aún colapsa una.',
    'settings.extraBody.help' => 'Campos de solicitud de nivel superior añadidos a cada solicitud del proveedor `custom`.',
    'settings.formatCommands.help' => 'Comando de formato post-edición por extensión de archivo ({"php": "vendor/bin/php-cs-fixer fix {file}"}); se ejecuta antes del lint post-edición y reescribe el archivo. Apagado por defecto.',
    'settings.formatAuto.help' => 'Permite que la tabla de extensiones integrada (gofmt, rustfmt, ruff/black, shfmt, terraform fmt, el prettier de node_modules del propio proyecto) formatee un archivo editado cuando `formatCommands` no nombra un comando para su extensión. Las entradas explícitas ganan; un proyecto aún necesita `trustedProjectHooks`. Apagado por defecto.',
    'settings.globMaxMatches.help' => 'Rutas que un Glob recoge antes de que su recorrido se detenga; el tope de salida aún limita el resultado.',
    'settings.grepTimeoutSeconds.help' => 'Segundos que una búsqueda de Grep puede ejecutarse antes de que se mate; los hallazgos hasta la fecha límite vuelven como resultado parcial.',
    'settings.hooksDefaultTimeoutSeconds.help' => 'Segundos que una entrada de hook sin `timeout:` puede ejecutarse antes de que se mate y cuente como rechazo.',
    'settings.includeGitInstructions.help' => 'Si la guía genérica de commits de la herramienta Bash viaja en el prompt de sistema.',
    'settings.instructions.help' => 'Globs de archivos cuyo contenido se convierte en texto autoritativo del prompt de sistema.',
    'settings.instructions.walkToRoot.help' => 'Opt-in: lee también archivos de instrucción por encima del marcador .git más cercano, hasta pero sin incluir el directorio home. Solo nivel de usuario; cada lectura conserva su presupuesto de contención y tamaño.',
    'settings.instructionsExclude.help' => 'Globs de archivos de instrucción para omitir, registrados como rechazos; solo nivel de usuario — un repositorio no puede silenciar a su operador. Los archivos dentro del checkout coinciden por ruta relativa al checkout; los archivos ancestro y forzados fuera de él coinciden por ruta absoluta, así que `**/CLAUDE.local.md` alcanza también las copias ancestro.',
    'settings.keybindings.help' => '{"shell.palette": "Ctrl+B"}: vincula un acorde EXTRA a un id de binding (la referencia /keys los nombra) — Ctrl+<key>, Alt+<key>, Shift+<key>, o una tecla de función sola; el acorde incluido sigue funcionando. Presente-pero-inutilizable rechaza el lanzamiento; elimina la tecla para los bindings incluidos.',
    'settings.layout.help' => 'El manifiesto de paneles acoplados; escrito por el shell cuando los paneles se mueven.',
    'settings.lintCommands.help' => 'Comando de lint post-edición por extensión de archivo ({"php": "…", "js": false}); `php -l` está integrado.',
    'settings.lsp.help' => '{"php": {"command": "intelephense", "args": ["--stdio"]}}: servidores para diagnósticos post-edición, esquemas de Read y la herramienta Lsp.',
    'settings.lspAutoDetect.help' => 'Inicia el servidor de lenguaje que la huella del proyecto nombra (composer.json → intelephense, package.json + tsconfig.json → typescript-language-server, pyproject.toml o setup.py → pyright-langserver, go.mod → gopls, Cargo.toml → rust-analyzer) cuando su binario está en PATH; las entradas `lsp` manuales ganan por lenguaje. Lanzar un servidor ejecuta ese servidor y el código de build en el árbol abierto, así que las huellas inician servidores solo en proyectos en los que has confiado para hooks; una raíz no confiable no inicia ninguno y registra la omisión en los avisos de lanzamiento.',
    'settings.maxCheckpoints.help' => 'Puntos de control de turno a los que /rewind puede volver, por sesión; los más antiguos se recortan más allá de esto.',
    'settings.maxCostUsd.help' => 'Rechaza nuevos turnos una vez que el gasto reportado por el proveedor de un lanzamiento alcance esta cantidad de dólares; sin definir no hay tope. /budget lo cambia solo para el lanzamiento en ejecución.',
    'settings.maxOutputTokens.help' => 'Techo de salida por solicitud; sin definir no envía sobrescritura y se aplica el predeterminado del proveedor.',
    'settings.maxToolSteps.help' => 'Llamadas al proveedor que un turno puede hacer; sin definir mantiene el predeterminado del motor.',
    'settings.mcp.enabled.help' => 'Inicia los servidores MCP que el .mcp.json de un proyecto confiable nombra; off no inicia ninguno y las superficies reportan el lanzamiento como deshabilitado.',
    'settings.mcp.lazySchemaTokens.help' => 'Tokens de esquema que un servidor MCP puede anunciar antes de que sus herramientas deleguen en mcp_list/mcp_call; 0 nunca delega.',
    'settings.mcpResultCapBytes.help' => 'Máximo de bytes que la respuesta de una herramienta MCP puede entregar al modelo.',
    'settings.memory.autoConsolidate.help' => 'Guarda hechos duraderos de turnos terminados en la memoria y pliega el registro de compactación en ella (la pasada de sueño); cada una es una llamada facturada.',
    'settings.memory.dreamIntervalSeconds.help' => 'Tiempo mínimo entre dos pasadas de sueño para un proyecto; cada pasada es un turno facturado, de solo lectura.',
    'settings.memory.dreamProposeSkills.help' => 'Permite que la pasada de sueño proponga habilidades como borradores en ~/.candy-code/skills-proposed; ninguna está activa hasta que tú la aceptes con /skills.',
    'settings.memory.entryMaxBytes.help' => 'Longitud máxima de la línea de índice de una nota antes de mostrarse truncada; se reduce al presupuesto de notas de usuario si lo supera.',
    'settings.memory.projectNoteMaxBytes.help' => 'Tamaño máximo que una nota de memoria de proyecto puede tener al escribirse en .candy-code/memory/ del repositorio.',
    'settings.memory.promptMaxBytes.help' => 'Presupuesto de bytes para las líneas de notas del índice de memoria; el presupuesto de notas de usuario se reduce para caber dentro.',
    'settings.memory.promptMaxEntries.help' => 'Máximo de notas que el índice de memoria del prompt lista, las más recientes primero; las notas de usuario cuentan dentro.',
    'settings.memory.userMaxBytes.help' => 'Presupuesto de bytes para las líneas de ámbito de usuario, dentro del presupuesto total.',
    'settings.memory.userMaxEntries.help' => 'Máximo de tus notas entre proyectos (ámbito de usuario) listadas primero, dentro del recuento de notas.',
    'settings.modelPrices.help' => 'USD por 1M de tokens por modelo ({"input": …, "output": …}), para el gasto total y el límite.',
    'settings.models.help' => 'El modelo a ejecutar, por proveedor ({"<provider>": "<model id>"}); sin definir usa el predeterminado del proveedor.',
    'settings.mouse.help' => 'Informa del ratón a candy-code (clics, rueda, selección); off devuelve al terminal su propio copiar-al-seleccionar.',
    'settings.mouseClicks.help' => 'Clics y arrastres actúan sobre lo que alcanzan; off mantiene la rueda e ignora los clics.',
    'settings.notices.transcriptLimit.help' => 'Máximo de advertencias de inicio asentadas como filas de transcripción; el resto se cuenta en una fila «y N más», y stderr las lleva todas.',
    'settings.notify.help' => 'off, bell (BEL) u osc9 (una notificación de escritorio): se envía cuando termina un turno y cuando el agente espera una aprobación.',
    'settings.paletteMru.help' => 'Cuántas filas de paleta usadas recientemente se recuerdan y se clasifican primero; 0 no recuerda ninguna.',
    'settings.parallelToolCalls.help' => 'Ejecuta concurrentemente las llamadas a herramientas de solo lectura de un turno.',
    'settings.parallelToolDeadlineSeconds.help' => 'Límite de tiempo real para un lote de llamadas a herramientas despachadas concurrentemente.',
    'settings.permissionMode.help' => 'Cómo se controlan las llamadas a herramientas. Nunca se toma de un archivo de proyecto.',
    'settings.permissionRules.help' => 'Reglas ordenadas permitir / denegar / preguntar que se comparan con cada llamada a herramienta. Un settings.json compartido de un proyecto de confianza puede aportar entradas denegar / preguntar — solo estrechando.',
    'settings.permissions.autoAllowReadOnly.help' => 'Bajo default y accept-edits, ejecuta una línea de Bash formada solo por comandos de solo lectura (ls, cat, grep, git log, …; sin redirección de archivos, sin sustitución, cd solo dentro del proyecto) sin preguntar. Un proyecto solo puede desactivarlo.',
    'settings.permissions.autoStrikeLimit.help' => 'Bajo auto, esta cantidad de llamadas bloqueadas de una categoría seguidas convierten la siguiente en una pregunta.',
    'settings.permissions.autoTotalLimit.help' => 'Bajo auto, una vez bloqueadas esta cantidad de llamadas en una sesión, cada bloqueo adicional te pregunta a ti.',
    'settings.pluginPaths.help' => 'Directorios adicionales escaneados para paquetes de plugins en formato Claude, junto a las dos raíces instaladas; un valor puede nombrar un paquete en sí o un contenedor de paquetes. Solo nivel de usuario — un checkout no puede inscribir sus propios plugins.',
    'settings.promptCache.keepWarm.help' => 'Pings de calentamiento permitidos por tramo de inactividad; 0 (predeterminado) es off. Cada ping reenvía el prefijo congelado de una sesión inactiva con una fila de instrucción pidiendo una respuesta de un carácter, para que el proveedor refresque su caché de prompt antes de que expire el TTL y el siguiente prompt no prefille toda la conversación sin caché. Solo se dispara donde el pliegue cacheTtl declinó — por debajo de su suelo o antes de su hora — en el mismo tick/alarm que ya ejecuta la vigilancia del pliegue, nunca a mitad de turno, nunca más de uno a la vez, nunca más allá de este recuento por tramo. Son llamadas facturadas a una sesión que nadie observa; el límite de gasto sigue aplicando. El recuento aparece en /usage bajo `warm`.',
    'settings.promptCache.help' => 'Si los proveedores `vertex` y `bedrock` marcan puntos de corte de caché de prompt.',
    'settings.promptSuggestionHistory.help' => 'Mensajes recientes (cada uno recortado a 2000 caracteres) que se muestran a la llamada de sugerencia de prompt.',
    'settings.promptSuggestions.help' => 'Tras cada turno, pregunta al modelo de título el mensaje que probablemente enviarás a continuación y muéstralo en gris en la caja de entrada vacía (→ lo acepta).',
    'settings.provider.help' => 'Qué proveedor LLM usa la sesión; cada prompt se envía a su host.',
    'settings.providerRetryAttempts.help' => 'Llamadas por solicitud al proveedor cuando falla transitoriamente (red, 5xx, 408, 429), incluida la primera; 1 nunca reintenta.',
    'settings.providerRetryBaseBackoffMs.help' => 'Espera antes del primer reintento de una llamada fallida al proveedor; cada espera posterior se duplica.',
    'settings.providers.help' => 'Definiciones de proveedor por nombre ({"<name>": {"type": …, "baseUrl": …, "apiKey": …, "model": …}}); cada entrada se superpone a los predeterminados de ese tipo. Solo nivel de usuario: un proyecto nunca debe mover a dónde se envía tu credencial.',
    'settings.queueMode.help' => 'steer (el agente lo lee en su siguiente paso), followup (enviado tras el turno) o interrupt (detiene el turno en su siguiente paso, luego envía). Tab siempre encola.',
    'settings.readMaxBytes.help' => 'Límite para una llamada Read; la página de abajo es el tamaño al que una lectura suele volver.',
    'settings.readPageBytes.help' => 'Bytes que una página de Read puede contener, números de línea incluidos, sea lo que pida `limit`.',
    'settings.readPageLines.help' => 'Líneas que un Read devuelve cuando la llamada no nombra `limit`.',
    'settings.reasoningEffort.help' => 'Nivel de pensamiento enviado donde el par lo configura: openai (serie o y gpt-5, no las builds -chat), anthropic y vertex (claude-3-7 y posteriores; vertex responde en ambos brazos claude y gemini), gemini (2.5 y posteriores), sglang (reenviado en cada solicitud), bedrock (ids claude, como presupuesto de pensamiento), codex y claude-code (niveles nombrados reenviados a la CLI); sin definir o no reconocido no pide nada. `/effort` lo establece y borra.',
    'settings.redactToolOutput.help' => 'Off por defecto: la salida de herramientas asentada se guarda en el historial y sessions.db exactamente como volvió. Cuando está on, cada resultado de herramienta pasa por el mismo redactor que protege la memoria y `/share` una vez asentado — credenciales reconocidas se convierten en `[REDACTED]` en los bytes que persisten y en lo que los turnos posteriores reproducen al modelo (la herramienta en sí sigue ejecutándose sin cambios). Campos de imagen, documento y uso pasan intactos. `/export` no añade redacción propia: imprime exactamente lo que se almacenó, así que lo guardado antes de activar esto permanece en crudo.',
    'settings.references.help' => 'Una lista de `[{"path": "…", "name": "…"}]` de directorios fuera del workspace que Read, Grep, Glob y Ls también pueden abrir, de solo lectura; cada uno se anuncia en el bloque `<env>` con un mapa limitado de lo que contiene. La jaula del workspace no cambia para Write, Edit y Bash — una referencia nunca amplía lo que se puede escribir. Solo nivel de usuario: un repositorio checkout no puede añadir una raíz de lectura. Una ruta inexistente o no-directorio, o una dentro de la raíz de sesión, se rechaza al inicio con un aviso.',
    'settings.repoMap.enabled.help' => 'Pon el mapa de dónde vive el código (paquetes y directorios de origen PSR-4) en el prompt del sistema.',
    'settings.repoMap.maxBytes.help' => 'Presupuesto de bytes para cada una de las dos secciones del mapa del repositorio; las entradas más allá se cuentan, no se listan.',
    'settings.requireReadBeforeWrite.help' => 'On, `Edit`, un `Write` que sobrescribe un archivo existente, y una sección `ApplyPatch` que cambia, mueve o borra uno, se niegan hasta que el modelo haya leído ese archivo en esta sesión; crear archivos nuevos nunca se bloquea. Off por defecto: los archivos que el modelo sí leyó siguen protegidos por la regla de cambio-en-disco de todos modos.',
    'settings.resumeCostWarnUsd.help' => 'Tras una reanudación obsoleta, el primer prompt se retiene una vez cuando reenviar el historial se estima que cuesta al menos esta cantidad de dólares sin caché; pulsa Enter de nuevo para enviar igualmente, o /compact primero. 0 desactiva la retención.',
    'settings.sandboxAllowedDomains.help' => 'Los hosts a los que la jaula `allowlist` puede llegar: nombres simples (`example.com`), comodines `*.example.com` y formas `host:port` (predeterminado: nada). Se usa solo cuando `bashSandbox` es `allowlist` en Linux; con una lista VACÍA `allowlist` se comporta EXACTAMENTE como `no-network`. El proxy de egreso concede HTTP(S) y nada más — cada host no listado recibe 403, y el tráfico no-HTTP (ssh, puertos de base de datos) falla. Una entrada malformada se IGNORA en la aplicación: un error tipográfico solo puede estrechar la concesión, nunca ampliarla. Solo nivel de usuario: un repositorio checkout no debe abrir un agujero en la jaula en la que llegó. macOS aplica `allowlist` como `no-network` — el brazo de puerto loopback es un seguimiento pendiente.',
    'settings.sandboxScope.help' => 'Qué comandos fuera de la ruta de herramientas se unen a la jaula `bashSandbox`: `hooks`, `lint`, `format`, `test`, `lsp`, `mcp` (predeterminado: ninguno). Solo activo mientras `bashSandbox` no es `off` — la lista dice quién comparte la jaula, nunca si existe una. Una entrada no reconocida se lee como TODOS los ámbitos (la más estricta, como un valor `bashSandbox` no reconocido), y la auditoría de ajustes la nombra. Una jaula que no puede arrancar rechaza el trabajo en vez de ejecutarlo libre: hooks de script deniegan, lint, format y test se omiten con la razón, y un servidor LSP o MCP stdio enjaulado no se inicia. Las entradas `lsp` y las MCP de nivel de usuario llevan una exclusión por servidor `"sandbox": false`; las exclusiones MCP de nivel de proyecto se ignoran.',
    'settings.screenReader.help' => 'Presentación para usuarios de lector de pantalla. On, la app desecha decoración que un lector no puede narrar — el spinner del agente se fija a un fotograma estático, y los marcos de dibujo de cajas, la selección de menú solo en vídeo inverso y similares dan paso a texto plano y una señal audible mientras cada superficie honra el cambio. Off es el terminal pintado como siempre. Tu propio ajuste de accesibilidad, como el modo vim de la caja de borrador: un proyecto checkout no puede cambiarlo. Se aplica en la siguiente lectura tras guardar — en vivo, sin recarga.',
    'settings.rules.standingMaxBytes.help' => 'Presupuesto de bytes, enmarcado y escapado, para los archivos de reglas insertados enteros en cada prompt; una regla más allá se nombra con una sola línea de puntero.',
    'settings.scrollWheelLines.help' => 'Líneas de transcripción que un tick de rueda desplaza.',
    'settings.sd.apiKey.help' => 'Clave Bearer enviada al servidor Stable Diffusion, si exige una; prefiere la forma de marcador de posición `${VAR}` sobre un literal.',
    'settings.sd.baseUrl.help' => 'URL base HTTP de un webui Stable Diffusion compatible con AUTOMATIC1111 (`http://127.0.0.1:7860`); prompts, imágenes y la clave API todos egresan ahí.',
    'settings.sd.defaultModel.help' => 'ID de modelo con el que empiezan las solicitudes de generación; el servidor guarda la elección para sí cuando no se define.',
    'settings.sd.presets.help' => 'Paquetes de parámetros nombrados que el formulario de medios ofrece; la forma es propia del pipeline de medios, opaca a la capa de ajustes.',
    'settings.sd.savePattern.help' => 'Plantilla de nombre de archivo para medios guardados; los tokens `[date]`, `[time]`, `[seed]` y `[number]` se rellenan al guardar.',
    'settings.sd.timeoutSeconds.help' => 'Segundos que una solicitud de generación puede ejecutarse antes de abandonarse; la difusión en una GPU débil rutinariamente tarda minutos.',
    'settings.secretEnvAllowlist.help' => 'Nombres de variables con forma de credencial (o globs) que Bash, Grep y hooks de script aún heredan.',
    'settings.server.allowBypass.help' => 'Si las sesiones del servidor pueden ejecutarse en bypass-permissions o dont-ask (igual que --allow-bypass).',
    'settings.server.allowedHosts.help' => 'Nombres de host (o host:port) a los que el servidor responde, junto a los nombres loopback y sus propias direcciones, p. ej. los de un proxy inverso.',
    'settings.server.allowedIps.help' => 'IPs de cliente o rangos CIDR permitidos a conectar, junto a loopback; cualquier otro se rechaza con 403 antes del inicio de sesión. Vacío: sin filtro de dirección.',
    'settings.server.allowedOrigins.help' => 'Orígenes de navegador adicionales (http(s)://host[:port]) que el servidor acepta, junto a los suyos propios.',
    'settings.server.askTimeoutSeconds.help' => 'Segundos que una pregunta de permiso espera a un cliente antes de rechazarse; 0 espera para siempre.',
    'settings.server.browseRoot.help' => 'El directorio al que server.dirBrowse está confinado (igual que --browse-root); sin definir es tu directorio personal.',
    'settings.server.dirBrowse.help' => 'Permite a clientes con sesión iniciada listar nombres de directorio bajo server.browseRoot e iniciar sesiones ahí (igual que --allow-dir-browse). Off por defecto.',
    'settings.server.clientTools.help' => 'Permite a clientes de ámbito Write registrar herramientas vía tools.client.register para que el modelo pueda llamar código que se ejecuta en el propio cliente (herramientas client__*). Off por defecto.',
    'settings.server.drainSeconds.help' => 'Segundos que un servidor en parada espera a los turnos en ejecución antes de cancelarlos; 0 se detiene de inmediato.',
    'settings.server.host.help' => 'La dirección a la que `serve` se enlaza. Cualquier cosa que no sea loopback también necesita --allow-remote al iniciar.',
    'settings.server.maxConcurrentTurns.help' => 'Turnos que un servidor ejecuta a la vez entre sus sesiones; uno más se rechaza por ocupado (reintentable).',
    'settings.server.maxOpenSessions.help' => 'Sesiones que un servidor mantiene abiertas a la vez; más allá, la inactiva menos usada recientemente se libera.',
    'settings.server.port.help' => 'El puerto al que `serve` se enlaza; 0 elige uno libre.',
    'settings.server.trustedProxies.help' => 'IPs o CIDRs cuyos X-Forwarded-For / X-Forwarded-Proto el servidor cree.',
    'settings.serviceTier.help' => 'Carril premium enviado donde el par lo configura: openai pide `service_tier: "priority"` en ambos brazos Chat y Responses, anthropic pide `speed: "fast"` (solo la familia claude-opus-5-5 GA y las familias claude-opus-5 / claude-opus-4-8 de research-preview, cuyo encabezado beta requerido viaja automáticamente); sin definir o no reconocido no pide nada. El modo rápido factura un premium que ninguna tabla de precios por clave de modelo puede derivar: mientras un par por niveles está activo, sus turnos caen en el libro como sin precio, nunca como una tasa adivinada. Se aplica al inicio y en cada reconstrucción de proveedor o modelo.',
    'settings.sessionRetentionDays.help' => 'Cada inicio borra sesiones sin nombre, sin fijar, intocadas durante esta cantidad de días y dice cuáles; 0 (el predeterminado) lo conserva todo.',
    'settings.sessions.autoTitle.help' => 'Nombra cada sesión nueva desde su primer turno con una llamada al modelo de título; off la deja sin nombre hasta /rename.',
    'settings.sessions.awayRecap.help' => 'Cuando el terminal informa del foco de vuelta tras haber estado ausente tres minutos o más, imprime un resumen de dónde quedó la sesión (una llamada al modelo de título por ausencia); off deja el regreso en silencio. `/recap` pide uno en cualquier momento.',
    'settings.skills.listingMaxBytes.help' => 'Presupuesto de bytes para toda la lista de habilidades en el prompt del sistema; las habilidades más allá colapsan en una línea «N habilidades más».',
    'settings.skills.pathNudges.help' => 'Cuando una herramienta toca un archivo que una habilidad de ámbito de ruta cubre, recuerda al modelo que esa habilidad existe, una vez por habilidad.',
    'settings.statusLine.help' => '{"type": "command", "command": "…", "refreshSeconds": 2}: un comando de shell cuya salida pinta la barra de estado, re-ejecutado cada refreshSeconds (2 a 3600, predeterminado 2). Recibe la sesión como un documento JSON en stdin (session_id, cwd, model, workspace, version, cost, más extras de candy_code); un comando que nunca lee stdin igualmente se ejecuta.',
    'settings.streamHeaderTimeoutSeconds.help' => 'Segundos que un servidor de streaming conectado puede tardar en enviar sus cabeceras de respuesta; nunca un timeout total de solicitud.',
    'settings.streamIdleTimeoutSeconds.help' => 'Segundos que una lectura de una respuesta en streaming puede esperar bytes antes de que la conexión se declare muerta; por lectura, nunca un total.',
    'settings.subagentMaxActive.help' => 'Ejecuciones delegadas que una sesión puede tener en marcha a la vez, contando cada nivel, miembro y agente en segundo plano; más allá, una llamada `Task` se rechaza. Sin definir — el predeterminado — o 0 no establece tope.',
    'settings.subagentMaxConcurrent.help' => 'Llamadas `Task` de un lote que se ejecutan a la vez (el resto espera un hueco libre), y el ancho de cada pool de agentes. Sin definir — el predeterminado — o 0 no establece tope.',
    'settings.subagentMaxDepth.help' => 'Niveles por debajo de la sesión que una ejecución delegada puede tener; una ejecución en el último nivel no recibe `Task`. 1 permite que los sub-agentes no deleguen más.',
    'settings.subagentMaxTurns.help' => 'Tope de pasos para un sub-agente — una delegación `Task`, una etapa de workflow o una ejecución `executeAgents` — cuyo preset no declara `maxTurns`.',
    'settings.subagentModel.help' => 'Modelo en el que un sub-agente delegado se ejecuta cuando su preset dice `inherit`; sin definir sigue el modelo de la sesión.',
    'settings.summaryModel.help' => 'Modelo que escribe resúmenes de compactación; sin definir usa el propio modelo de la conversación, que reutiliza la caché de prompt.',
    'settings.symbolMap.enabled.help' => 'Pon el mapa de repositorio clasificado a nivel de símbolo en el prompt del sistema, capturado una vez por sesión.',
    'settings.temperature.help' => 'Temperatura de muestreo que el proveedor `custom` envía cuando una solicitud no nombra ninguna.',
    'settings.terminalBackground.help' => 'Qué asume el tema adaptativo detrás del texto: auto pregunta al terminal (OSC 11, luego COLORFGBG); light o dark lo dice de frente.',
    'settings.testCommand.help' => 'Comando de shell que ejecuta las pruebas del proyecto, en la raíz del proyecto (`composer test`, `pytest -q`); lo que `autoTest` ejecuta.',
    'settings.theme.help' => 'Tema de color; /theme y la paleta lo cambian en vivo. Los temas personalizados se cargan desde archivos JSON en ~/.candy-code/themes.',
    'settings.thinkingBudget.help' => 'Presupuesto de tokens de razonamiento: `thinkingConfig` en el proveedor `vertex`; razonamiento extendido en el proveedor `anthropic`, donde el mínimo de la Messages API es 1024 (0 o sin definir significa desactivado en ambos). Los tokens de razonamiento se facturan como salida.',
    'settings.titleModel.help' => 'Modelo que nombra sesiones y escribe sugerencias de prompt; sin definir usa el predeterminado auxiliar barato del tipo de proveedor antes del modelo de bloque.',
    'settings.transcriptJsonl.help' => 'Refleja cada transcripción confirmada en un diario JSONL de solo-adjuntos bajo `~/.candy-code/transcripts/<project>/` (archivos 0600), y pasa a los scripts de hook una clave `transcript_path` en stdin que apunta a él. El diario guarda la conversación en crudo y crece sin límite; se lee al iniciar, así que un cambio se aplica en el siguiente arranque.',
    'settings.toolInstructionCapBytes.help' => 'Máximo de bytes del cuerpo de un CLAUDE.md/AGENTS.md rector que un resultado de Edit, Write o ApplyPatch puede llevar; el resto se corta con un marcador.',
    'settings.toolOutputCapBytes.help' => 'Máximo de bytes que un resultado de Bash, Grep, Glob, Lsp o WebFetch puede entregar al modelo; lo cortado se guarda en un archivo que el resultado nombra.',
    'settings.toolOutputPreviewLines.help' => 'Líneas de un resultado de herramienta colapsado mostradas en la transcripción; Ctrl+O expande el resto.',
    'settings.toolSpillCaptureBytes.help' => 'Máximo de la salida de un comando Bash (por flujo) retenido en memoria y guardado en el archivo de volcado cuando el resultado se corta; nunca por debajo del tope de salida.',
    'settings.toolSpillMinCapBytes.help' => 'Tope mínimo de resultado a partir del cual un resultado de herramienta cortado se guarda en un archivo; por debajo se anuncia el corte y se descarta el resto.',
    'settings.toolSpillWindowPercent.help' => 'Mayor proporción de la ventana de contexto que un resultado de herramienta puede ocupar; al superarla, el resultado se guarda en un archivo y al modelo se le muestra su inicio y fin.',
    'settings.trustedProjectCommands.help' => 'Raíces de proyecto cuyos comandos de barra pueden ejecutar bloques de shell !`cmd`.',
    'settings.trustedBundleCommands.label' => 'Comandos de bundle confiables',
    'settings.trustedBundleCommands.help' => 'Nombres de bundles de plugin cuyos archivos de comandos pueden ejecutar bloques de shell !`cmd`; cada comando sigue siendo juzgado por la puerta de permisos. Los nombres coinciden con el nombre del manifiesto del propio bundle, y solo cuentan las instalaciones de nivel de usuario — un checkout de proyecto no puede otorgarse shell a sí mismo, ni siquiera usurpando un nombre listado. Optar no es un bypass: en la puerta solo una regla Deny niega, y una regla que la puerta califica como Ask se ejecuta sin supervisión — la expansión no tiene prompt que mostrar. Vacío por defecto, por lo que los comandos de bundle no ejecutan shell.',
    'settings.mcpPromptShell.label' => 'Shell de prompt MCP',
    'settings.mcpPromptShell.help' => 'Claves de servidores MCP cuyos cuerpos de prompt pueden ejecutar bloques de shell !`cmd`; cada comando sigue siendo juzgado por la puerta de permisos. Los nombres coinciden con la clave que su configuración de usuario da al servidor. Solo nivel de usuario; vacío por defecto, por lo que los prompts obtenidos no ejecutan shell. Optar no es un bypass: en la puerta solo una regla Deny niega, y una regla que la puerta califica como Ask se ejecuta sin supervisión — la expansión no tiene prompt que mostrar.',
    'settings.trustedProjectHooks.help' => 'Raíces de proyecto cuyos .candy-code/hooks.yaml pueden ejecutarse.',
    'settings.trustedProjectMcp.help' => 'Raíces de proyecto cuyos servidores .mcp.json pueden lanzarse.',
    'settings.trustedProjectSettings.help' => 'Raíces de proyecto cuyos .candy-code/settings*.json pueden establecer las claves del nivel de proyecto.',
    'settings.turnIdleTimeoutSeconds.help' => 'Segundos que un turno en ejecución puede pasar sin ningún progreso antes de detenerse como colgado; tiempo inactivo, nunca un total.',
    'settings.ui.imageRenderMode.help' => 'Cómo se pintan las imágenes generadas en el terminal; `auto` elige el mejor protocolo que el terminal informa.',
    'settings.ui.mediaDisplayOverrides.help' => 'Ajustes de visualización por modo de renderizado (topes de tamaño, alternativas); las claves son las palabras del modo de renderizado, los valores los controles de visualización.',
    'settings.vimMode.help' => 'Edición NORMAL/INSERT en el cuadro de borrador (i a I A o O Esc, h j k l w b e 0 $ x, dd D cc C yy y p P v V, objetos de texto di" da( ciw, conteos 3dd d2w): movimientos, cambio, borrado y yank en NORMAL, escritura literal en INSERT. Un modo, no atajos — nunca aparece en /keys. Se aplica en la siguiente pulsación tras guardar.',
    'settings.voice.apiKey.help' => 'Clave Bearer enviada al endpoint de transcripción, si lo exige; prefiere la forma de marcador `${VAR}` sobre un literal.',
    'settings.voice.baseUrl.help' => 'URL base HTTP de un endpoint de transcripción compatible con OpenAI (un `/v1` final se conserva); la grabación sale solo por ahí y por ningún otro sitio. Sin predeterminado: la entrada de voz permanece OFF hasta que se defina en el nivel de usuario.',
    'settings.voice.language.help' => 'Código BCP-47 (`en`, `de`) que fuerza el idioma de transcripción; sin definir deja que el endpoint lo detecte.',
    'settings.voice.maxSeconds.help' => 'Tope duro de segundos en una grabación (5-600, predeterminado 120). El tope viaja en el argumento del grabador, así que una grabación huérfana se detiene sola.',
    'settings.voice.model.help' => 'ID de modelo enviado con cada solicitud de transcripción; `whisper-1` responde en endpoints compatibles con OpenAI.',
    'settings.watchFiles.help' => 'Envía un prompt cuando un archivo guardado contiene un comentario terminado en AI! (hacer un cambio) o AI? (responder una pregunta); los comentarios AI simples viajan como contexto. Se consulta mientras el chat está inactivo; solo se disparan, una vez cada uno, los comentarios guardados tras el arranque. Solo sesiones de terminal: el vigilante corre en el proceso del terminal, así que una sesión alojada por `candy-code serve` no vigila archivos.',
    'settings.webFetchMaxBytes.help' => 'Máximo del cuerpo obtenido retenido en memoria; un límite de memoria, el tope de salida es lo que llega al modelo.',
    'settings.webFetchTimeoutSeconds.help' => 'Segundos que una lectura de socket de WebFetch puede estancarse antes de que la obtención falle.',
    'settings.webSearchBackend.help' => 'Qué servicio de búsqueda consulta WebSearch: `searxng` (el predeterminado) envía cada consulta al `webSearchEndpoint` configurado; `brave`, `tavily` y `exa` llaman al host fijo de ese servicio y cada uno necesita su clave API en el entorno (`BRAVE_SEARCH_API_KEY`, `TAVILY_API_KEY`, `EXA_API_KEY`), sin forma de apuntarlos a otra URL.',
    'settings.webSearchEndpoint.help' => 'URL de búsqueda de una instancia SearXNG de confianza (`https://searx.example.org/search`); cada consulta de WebSearch se envía ahí.',
    'settings.webSearchMaxResults.help' => 'Resultados que un resumen de WebSearch lista, cada uno con título, URL y fragmento.',
    'settings.webSearchTimeoutSeconds.help' => 'Segundos que una solicitud de búsqueda puede tardar.',
    'settings.webhooks.help' => 'Mapa de nombre de hook a {secret, prompt, permissionMode?, rate?}; POST /api/hooks/{name} luego inserta el cuerpo (escapado como no confiable) en el prompt e inicia una sesión en segundo plano. Vacío (predeterminado) no monta nada. rate es N entregas por minuto por dirección, y por hook en total. bypass-permissions se rechaza para hooks al iniciar; un hook sin modo corre en el más estricto del modo del servidor y el predeterminado. Una fila también puede nombrar signature: {scheme: "github-sha256"|"hmac-sha256", header?, deliveryHeader?}: la ruta entonces verifica un HMAC-SHA256 del cuerpo en crudo (sha256=<hex>) con el secret de la fila a través del encabezado de firma, en lugar del secret del encabezado personalizado, porque GitHub no puede enviar encabezados personalizados; las firmas fallidas alimentan el mismo bloqueo por hook, y un id de entrega ya visto (X-GitHub-Delivery por defecto para el esquema GitHub; el deliveryHeader configurado para uno genérico) responde {"ok": true, "duplicate": true} sin iniciar una segunda sesión.',
    'settings.webhooksOut.help' => 'Mapa de nombre de endpoint a {url, secret, events}; events es una lista no vacía tomada de turn.completed, session.ended, permission.asked y schedule.fired. Vacío (predeterminado) no abre ninguna salida. Se lee solo del nivel USER — una configuración de proyecto o bundle nunca puede añadir un endpoint saliente. url debe ser https, o http solo cuando su host literal es localhost o una dirección de loopback, y nunca lleva userinfo; secret tiene al menos 16 caracteres y firma cada entrega con HMAC-SHA256 como X-Candy-Code-Signature (sha256=<hex> sobre el cuerpo exacto) junto con X-Candy-Code-Timestamp. La entrega es asincrónica en el bucle de eventos — los despachos nunca esperan una respuesta: un límite de conexión de 2 segundos y un tope de red de 10 segundos por POST acotan cada entrega (límites de webhook, no un tiempo de espera de solicitud LLM), los fallos de transporte y las respuestas 5xx suben una escalera de reintentos de 2/8/30 segundos, las respuestas 4xx y de redirección son definitivas a la primera porque las redirecciones se rechazan en lugar de seguirse, y una cola acotada de 128 entregas en vuelo descarta nuevos despachos al desbordar en lugar de crecer en memoria. Se lee al iniciar; cambiar el mapa surte efecto al reiniciar.',
    'settings.webhooksOut.refuse' => 'webhooksOut en la configuración de usuario no es utilizable: {reason}. Se rechaza iniciar en lugar de entregar a un endpoint a medio verificar — corrige el mapa, o elimina la clave para ejecutar sin webhooks salientes.',
    // --- end settings help ---

