    'session.import.notice' => 'Transcripción {format} importada — material de referencia no confiable: su actividad de herramientas se registra como texto, nunca se reproduce.',
    'session.import.refusal.not_readable' => 'import: {path} no es un archivo legible, así que no se importó nada',
    'session.import.refusal.source_shrank' => 'import: la fuente ahora contiene menos filas de transcripción que las almacenadas en la última importación, y una transcripción encogida se rechaza en lugar de reescribirse',
