    'session.import.refusal.unknown_format' => 'import: el archivo no coincide con una transcripción de CandyCode, Claude Code, Codex u OpenCode, así que no se adivinó nada',
    'session.import.refusal.unsupported_shape' => 'import: la forma de la transcripción no se reconoce ({detail}); los formatos desconocidos se rechazan, nunca se adivinan',
